const EVENTS=[{id:'roll',q:'started rolling?',key:'rolling',after:'Rolling is here',help:'We’ll bring movement and safety guidance into this month.',min:3,max:7},{id:'solids',q:'started solids?',key:'firstfoods',after:'First foods are here',help:'We’ll show guidance for first meals instead of preparation.',min:5,max:9},{id:'tooth',q:'a first tooth yet?',key:'teeth',after:'A first tooth is here',help:'We’ll bring tooth care into this month.',min:4,max:12},{id:'crawl',q:'started crawling or scooting?',key:'safety',after:'A bigger world to explore',help:'We’ll bring movement safety into this month.',min:6,max:12}];
function eventQuestion(ev){return ev.id==='tooth'?`Does ${name()} have a first tooth yet?`:`Has ${name()} ${ev.q}`}function currentEvent(){const dm=developmentMonth();const suitable=EVENTS.filter(e=>dm>=e.min&&dm<=e.max);return suitable.find(e=>e.id===currentCheckId)||suitable.find(e=>!answers[e.id])||suitable.find(e=>answers[e.id]!=='Yes')||suitable[0]||null}
function activeFocus(){const st=STAGES[developmentMonth()];let key=st.key;const feedAge=month; if(feedAge===5)key=answers.solids==='Yes'&&isCurrent()?'firstfoods':'solids';if(feedAge===6)key='firstfoods';const out=[{key,title:GUIDES[key].title,line:GUIDES[key].focus}];if(isCurrent()){const ev=EVENTS.find(e=>answers[e.id]==='Yes'&&e.key!==key);if(ev)out.push({key:ev.key,title:GUIDES[ev.key].title,line:GUIDES[ev.key].focus,new:true})}if(out.length===1&&month>=5&&month<8&&key!=='safety')out.push({key:'safety',title:'A safer space to explore',line:'A few useful things to notice as movement changes.'});return out.slice(0,2)}
function expectation(){const dm=developmentMonth();if(dm>=3&&dm<=5)return {key:'sleep',label:dm===3?'Coming up':'Could be happening now',line:'What to notice if nights feel different.'};if(month>=4&&month<=7)return {key:'teeth',label:'Could be happening now',line:'A guide for whenever that first tooth arrives.'};if(dm>=8)return {key:'separation',label:'Could be happening now',line:'A little reassurance for bigger goodbyes.'};return {key:'rhythm',label:'In this stage',line:'Small patterns may start to feel familiar.'}}
const pageMonths={};function rememberScroll(){savedGuideNotice='';captureReadingState();scrollPositions[page]=window.scrollY||0;pageMonths[page]=month}function navigate(p){currentCheckId=null;rememberScroll();historyStack=[];if(['home','categories','year','timeline','explore','saved'].includes(p))month=actualMonth();page=p;query='';render();window.scrollTo(0,scrollPositions[p]||0)}function openGuide(k){rememberScroll();historyStack.push(page);page='guide:'+k;render();window.scrollTo(0,0)}function openPage(p){rememberScroll();historyStack.push(page);if(p==='personalize')month=actualMonth();page=p;render();window.scrollTo(0,0)}function back(){if(page==='setup'&&setupStep===2){draft.feed=$('#feed').value;setupStep=1;render();window.scrollTo(0,0);return}page=historyStack.pop()||'home';if(pageMonths[page]!==undefined)month=pageMonths[page];render();window.scrollTo(0,scrollPositions[page]||0)}function setMonth(m){month=m;currentCheckId=null;render()}function saveTopic(t){saveGuide('topic:'+t)}function saveGuide(k){saved.includes(k)?saved=saved.filter(x=>x!==k):saved.push(k);persist();const y=window.scrollY;render();window.scrollTo(0,y)}function setAnswer(id,a){releaseJourneyFact(id);if(page==='home')currentCheckId=id;if(a)answers[id]=a;else delete answers[id];if(['roll','rollDirection','crawl','pullUp'].includes(id))markStage('movement');persist();const y=window.scrollY;render();window.scrollTo(0,y)}function footer(){return '<div class="foot"><button onclick="openPage(\'trust\')">How we choose sources</button><div>Design prototype · Based on AAP and CDC guidance</div></div>'}function backButton(){const dest=historyStack[historyStack.length-1]||'home',labels={categories:'Categories',timeline:'Memories',home:'Home',explore:'Resources',saved:'Saved',profile:'Baby’s details',personalize:'Baby’s updates',ahead:'Looking ahead',welcome:'Welcome'},label=page==='setup'&&setupStep===2?'Baby’s details':dest.startsWith('chg:')&&/:(s|d|e):/.test(dest)?'Back':dest.startsWith('chg:')?displayTopic(dest.split(':')[1]):dest.startsWith('topic:')?displayTopic(dest.slice(6)):dest.startsWith('year:')?displayTopic(dest.slice(5))+' · Year view':dest==='year'?'Year views':labels[dest]||'Back';return `<button class="back" onclick="back()" aria-label="${label==='Back'?'Back':'Back to '+esc(label)}">${icon('back')} ${esc(label)}</button>`}function topicGrid(){return '<div class="topics">'+TOPICS.map(([t,i])=>`<button class="topic" onclick="openPage('topic:${t}')">${icon(i)}${displayTopic(t)}</button>`).join('')+'</div>'}function guideRow(k){if(k.startsWith('view:'))return savedViewRow(k);if(k.startsWith('topic:')){const t=k.slice(6);return `<button class="row" onclick="openSavedTopic('${t}')"><div class="grow"><h3>${displayTopic(t)}</h3><p>Current guidance · Category shortcut</p></div><span class="arrow">${icon('arrow')}</span></button>`}let g=GUIDES[k];return `<button class="row" onclick="${page==='saved'?'openSavedGuide':'openGuide'}('${k}')"><div class="grow"><h3>${g.title}</h3><p>${g.topic} · 2 min read</p></div><span class="arrow">${icon('arrow')}</span></button>`}

