function developmentBriefBeforeRework(dm){
 if(dm<=2)return {title:'Your voice.<br>A familiar place.',body:'In a very new world, your face and voice give your baby something familiar to return to. You may notice more looking, settling and small responses during everyday moments together.',small:'Watch what holds their attention, and give them a break when they turn away.',src:'https://www.cdc.gov/act-early/milestones/2-months.html',label:'CDC · early connection'};
 if(dm<=4)return {title:'A little conversation<br>is beginning.',body:'A sound from you may bring a sound back. A smile can invite another smile. These little exchanges are an early way for your baby to take part in the world around them.',small:'Pause after you respond. That space gives them a turn.',src:'https://www.cdc.gov/act-early/milestones/4-months.html',label:'CDC · early back-and-forth'};
 if(dm<=6)return {title:'A whole world<br>in their hands.',body:'You may notice a toy going straight from their hand to their mouth. This is exploration: your baby is getting to know an object by reaching for it, holding it and bringing it closer.',small:'Offer safe objects to explore while you supervise, and follow what catches their interest.',src:'https://www.cdc.gov/act-early/milestones/6-months.html',label:'CDC · exploration around 6 months'};
 if(dm<=9)return {title:'Out of sight.<br>Still interesting.',body:'A dropped toy can become something worth looking for. As your baby explores, you may notice more interest in where objects—and familiar people—go.',small:'A simple game with an object you hide while they watch gives you something to explore together.',src:'https://www.cdc.gov/act-early/milestones/9-months.html',label:'CDC · discovery around 9 months'};
 return {title:'Little gestures.<br>Shared meaning.',body:'A wave, a familiar name or a favorite game can carry a message between you. Your baby may be finding more ways to join in, even before they have many words.',small:'Respond to their gestures and attempts at words. Ordinary exchanges are opportunities to connect.',src:'https://www.cdc.gov/act-early/milestones/1-year.html',label:'CDC · communication toward 12 months'};
}
function briefingItems(){const dm=developmentMonth(),items=[];
if(month<=1)items.push({title:'Sleep comes in little stretches.',body:'Newborn sleep is spread across day and night, often in short stretches. A regular sleep pattern takes time to develop.',help:'Keep nighttime care quiet and gentle. Different babies have different sleep needs.',resource:'aap',link:'For the sleep basics: HealthyChildren',key:'sleep'});
if(dm>=3&&dm<=5)items.push({title:'Sleep may feel different.',body:'Sleep cycles become more regular around four months. Your baby’s pattern can change; a month on the calendar doesn’t mean a regression is inevitable.',help:'Keep nights calm and consider hunger, comfort and illness when waking changes.',resource:'aap',link:'For sleep questions: HealthyChildren',key:'sleep'});
if(month>=4&&month<=5&&!(isCurrent()&&answers.solids==='Yes'))items.push({title:month===4?'Solids are on the horizon.':'Food is getting interesting.',body:'Starting solids is generally around six months, with readiness signs such as head control, supported sitting and swallowing food. Watching your plate is only part of the picture.',help:profile.early?'Because your baby was born early, talk about individual readiness with your pediatrician.':'For now, get familiar with readiness. There’s no need to start because a new month arrived.',resource:'solids',link:'When you need food-prep help: Solid Starts',key:'solids'});
if(month===6||(isCurrent()&&answers.solids==='Yes'))items.push({title:'First foods are a new skill.',body:'Breast milk or formula remains important as foods are introduced. Sitting, head control and swallowing help guide readiness.',help:'Ask your pediatrician about timing and individual feeding needs. Food preparation matters alongside readiness.',resource:'solids',link:'For preparing a specific food: Solid Starts',key:'firstfoods'});
if((dm===3||dm===4)||(isCurrent()&&answers.roll==='Yes'))items.push({title:'Movement changes sleep safety.',body:'Stop swaddling when your baby shows signs of trying to roll; don’t wait for a completed roll. Continue placing your baby on their back for sleep on a firm, flat, clear surface.',resource:'aap',link:'For the exact safety guidance: AAP',key:'rolling'});
if(dm===8||dm===9)items.push({title:'Goodbyes can feel bigger.',body:'Reacting when you leave is part of the nine-month developmental guide. You might see reaching, looking for you or crying at a goodbye.',resource:'cdc',link:'For understanding this stage: CDC',key:'separation'});
if(dm>=10)items.push({title:'A new reach means a new look at home.',body:'Pulling up and holding furniture bring more things within reach. Revisit the spaces your baby explores as those skills appear.',resource:'cdc',link:'For movement and play ideas: CDC',key:'safety'});
return items;}
function resourceLink(id,label){return `<button class="turnto" onclick="openPage('resource:${id}')">${icon('explore')}<span>${label}</span><span aria-hidden="true">↗</span></button>`}
function resourceRow(id){const r=RESOURCE[id];return `<button class="resource-row" onclick="openPage('resource:${id}')"><div class="grow"><h3>${r.title}</h3><p>${r.use}</p><div class="resourcecost">${r.cost}${r.commercial?' · Optional commercial resource':''}</div></div><span class="arrow">${icon('arrow')}</span></button>`}
function stageResources(){return ['cdc','aap',...(month>=4?['solids']:[]),...(month>=3?['cara']:[])]}
function resourcePageBeforeRework(id){const r=RESOURCE[id];return backButton()+`<div class="detailhead"><div class="eyebrow">Where to turn · ${r.commercial?'Optional specialist support':'Pediatric education'}</div><h1>${r.title}</h1><p>${r.use}</p><span class="resourcebadge ${r.commercial?'optional':''}">${r.cost}</span></div><section class="block"><h2>When it’s useful</h2><p>${r.when}</p></section><section class="block"><h2>Why it’s here</h2><div class="reviewrow"><b>Who’s behind it</b><p>${r.who}</p></div><div class="reviewrow"><b>Evidence and expertise</b><p>${r.evidence}</p></div><div class="reviewrow"><b>What it doesn’t replace</b><p>${r.limits}</p></div></section><div class="verification"><h3>${r.commercial?'Optional paid resource':'Established institutional source'}</h3><p>${r.commercial?'Included here as a resource to evaluate, not a completed four-part endorsement. Check whether it fits your family before paying.':'The publisher and linked guidance have been checked. Ahead summarizes it in plain language.'} No paid placement or affiliate links in this prototype.</p></div><a href="${r.url}" target="_blank" rel="noopener" class="primary" style="display:block;text-align:center;text-decoration:none">Visit ${r.title} ↗</a><details class="source" style="margin-top:24px"><summary style="cursor:pointer;font-size:12px">See the source checks</summary>${r.refs.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${t} ↗</a><br>`).join('')}<p>Checked October 14, 2026. Costs and availability can change.</p></details>`}
function homeBrief(){const dm=developmentMonth(),b=developmentBrief(dm),notes=briefingItems();return `<div class="meta"><span class="statusdot"></span>${name()} · ${monthLabel(birthdayAge())}${profile.example?' · Example baby':''}</div><nav class="monthstrip" aria-label="Browse months">${STAGES.map((s,i)=>`<button class="month ${month===i?'active':''} ${i===actualMonth()?'current':''}" onclick="setMonth(${i})" aria-label="${monthLabel(i)}" aria-pressed="${month===i}"><b>${i===0?'N':i}</b><span>${i===0?'newborn':'mo'}</span></button>`).join('')}</nav><div class="monthinfo"><span>${isCurrent()?'What’s relevant now':'Looking '+(month>actualMonth()?'ahead':'back')}${profile.early?' · Development & play: '+monthLabel(dm)+' adjusted':''}</span>${!isCurrent()?'<button class="textlink" onclick="setMonth(actualMonth())">Back to now</button>':profile.early?'<button class="textlink" onclick="openPage(&quot;age-context&quot;)">About age</button>':''}</div><section class="briefhero"><div class="eyebrow">${name()}’s world at this stage</div><h1>${b.title}</h1><p class="lead">${b.body}</p><p class="everyday">${b.small}</p><a class="quietsource" href="${b.src}" target="_blank" rel="noopener">Based on ${b.label} ↗</a></section>${notes.map(n=>`<section class="briefnote"><h2>${n.title}</h2><p>${n.body}</p>${n.help?`<p class="takeaway">${n.help}</p>`:''}${resourceLink(n.resource,n.link)}</section>`).join('')}<div class="chapterend">${month<12?`<button onclick="setMonth(${month+1});window.scrollTo(0,0)"><div><div class="eyebrow">A glance ahead · ${monthLabel(month+1)}</div><h3>${STAGES[month+1].focus}</h3></div>${icon('arrow')}</button>`:'<p class="hint">Year two is the next chapter for Ahead.</p>'}</div><div class="foot"><button onclick="openPage('trust')">Sources, review and how we choose</button><div>Prototype</div></div>`}


function baseSnapshot(t){const dm=developmentMonth(),current=isCurrent(),started=current&&answers.solids==='Yes',notStarted=current&&['Not yet','Not sure'].includes(answers.solids),tooth=current&&answers.tooth==='Yes';
const feedingPrep=month>=4&&(month<6||notStarted);
const snapshots={
Development:{title:dm<=2?'Faces & first smiles':dm<=4?'Coos & head control':dm<=6?'Rolling & supported sitting':dm<=9?'Sitting & babbling':'Gestures & new moves',body:dm<=2?'Notice responses to your voice and face as the early stage unfolds.':dm<=4?'The four-month guide includes cooing and steadier head control.':dm<=6?'The six-month guide includes tummy-to-back rolling and leaning on hands to sit.':dm<=9?'The nine-month guide includes sitting without support and repeated babbles.':'The first-birthday guide includes waving, familiar names and pulling up.',key:'play',resource:'cdc',status:''},
Feeding:{title:started?'First tastes':month<4?'Follow feeding cues':feedingPrep?'Before the first bites':month<10?'Learning to eat':'Growing into meals',body:month<4?'Turning toward a feed or closing their mouth can tell you about hunger or fullness.':feedingPrep&&!started?'Look for head control, supported sitting and swallowing. Starting is generally around six months.':'Milk still matters as foods are introduced. Readiness and safe preparation go together.',key:month<4?'newborn':feedingPrep&&!started?'solids':'firstfoods',resource:month<4?'aap':'solids',status:started?'From your check-in':feedingPrep?'Coming up':'At this stage'},
Sleep:{title:month<3?'Short sleep stretches':dm<=5?'Changing sleep cycles':'Quiet nighttime care',body:month<3?'Sleep is spread across day and night. Regular patterns take time.':dm<=5?'Cycles become more regular around four months. Changes vary between babies.':'Keep nighttime voices soft and care gentle. Consider hunger, comfort or illness when waking changes.',key:'sleep',resource:'aap',status:dm===3?'Coming up':dm>=4&&dm<=5?'Could be happening now':''},
Health:{title:month<4?'Bring your questions':month>10?'Your next well visit':tooth?'A tooth has arrived':'Teething signs',body:month<4?'Keep feeding, growth and everyday concerns close for your pediatrician.':month>10?'Bring feeding and development questions to the first-birthday visit.':tooth?'Comfort and tooth-care questions move into focus. Ask your pediatrician about first-tooth care.':'Chewing and drool can accompany teething. Fever should not be attributed to teeth.',key:month<4?'newborn':month>10?'birthday':'teeth',resource:month>=4&&month<=10?'teething':'care',status:tooth?'From your check-in':month>=4&&month<=10?'Could be happening now':''},
Safety:{title:dm<3?'Every sleep, safely':dm<7?'Rolling & swaddling':'A bigger reach',body:dm<3?'Back to sleep, on a firm, flat surface with a fitted sheet and no soft objects.':dm<7?'Stop swaddling at signs of trying to roll—before a completed roll.':'Revisit your baby’s space as reach and movement change.',key:dm<7?'rolling':'safety',resource:dm<7?'safesleep':'cdc',status:''},
'Daily rhythm':{title:month<3?'Daytime connection':'A quiet wind-down',body:month<3?'Talk and play during daytime moments; keep nighttime feeds and changes quiet.':'Dim the activity at night: soft voices and gentle care help keep things calm.',key:'rhythm',resource:'aap',status:''}
};return snapshots[t];}
function mobileArt(){return `<svg class="heroart" viewBox="0 0 120 160" fill="none" aria-hidden="true"><path d="M67 1v24m-46 9q47-26 84 0M30 30v30m31-40v49m38-39v58" stroke="#86946b" stroke-width="1.3" stroke-linecap="round"/><circle cx="29" cy="71" r="14" fill="#e7c979"/><path d="M63 62c-10 0-16 9-16 19 0 15 25 24 25 24s19-20 15-31c-4-11-16-13-24-12Z" fill="#a8b78b"/><path d="M94 91q-9 10-2 22 6 7 17 3-9 0-12-9-4-9-3-16Z" fill="#d3b5a4"/><path d="M27 117l2 5 5 2-5 2-2 5-2-5-5-2 5-2 2-5Z" fill="#bdc997"/><circle cx="96" cy="141" r="3" fill="#b4bf95"/></svg>`}

RESOURCE.toothcare={...RESOURCE.care,title:'AAP · First-tooth care',use:'For “a tooth is here—what changes now?”',when:'As soon as a first tooth appears.',url:'https://www.healthychildren.org/English/ages-stages/baby/teething-tooth-care/Pages/Babys-First-Tooth-Facts-Parents-Should-Know.aspx',evidence:'AAP parent guidance on brushing, fluoride and the first dental appointment.',refs:[['AAP first-tooth guidance','https://www.healthychildren.org/English/ages-stages/baby/teething-tooth-care/Pages/Babys-First-Tooth-Facts-Parents-Should-Know.aspx']]};
function milkName(){return profile.feed==='Breast milk'?'Breast milk':profile.feed==='Formula'?'Formula':'Breast milk or formula'}
function stageSnapshotBeforeRework(t){const s=baseSnapshot(t);if(!isCurrent())return s;
if(t==='Feeding'){s.body=s.body.replace('Milk still matters',milkName()+' still matters');if(answers.solids==='Yes'){s.title='First tastes';s.key='firstfoods';s.status='From your check-in';s.body=milkName()+' remains important while your baby explores new foods.'}}
if(t==='Health'&&answers.tooth==='Yes'){Object.assign(s,{title:'A first tooth, new care',body:'Tooth care begins now. Start brushing and plan a first dental visit.',key:'teeth',resource:'toothcare',status:'From your check-in'})}
if(t==='Safety'&&answers.crawl==='Yes'){Object.assign(s,{title:'A space for moving',body:'Crawling or scooting changes what’s reachable. Look at the room from floor level.',key:'safety',resource:'cdc',status:'From your check-in'})}
else if(t==='Safety'&&answers.roll==='Yes'){s.title='A bigger reach';s.body='Check raised surfaces, hot drinks and the spaces baby can reach.';s.status='From your check-in'}
if(t==='Sleep'&&answers.sleepNeed==='Sleep has changed'){s.title='When nights change';s.body='Consider hunger, comfort and illness alongside development. A change isn’t automatically a regression.';s.status='You mentioned a change'}
return s;}
const QUESTIONCOPY={roll:{why:'Helps us show the relevant movement and safety guidance.',yes:'Rolling guidance is now current. Safety reminders stay visible even before rolling.'},solids:{why:'Switches feeding from preparation to first-meal guidance.',yes:'Feeding now focuses on first foods, with milk still part of the picture.'},tooth:{why:'Adds tooth care when a first tooth arrives.',yes:'Health now includes brushing and planning a dental visit.'},crawl:{why:'Helps us match safety guidance to new movement.',yes:'Safety now focuses on the spaces your baby can explore.'}};
function personalQuestion(ev){if(ev.id==='solids')return feedingStagePicker();if(ev.id==='roll')return movementQuestion();const a=answers[ev.id];return `<section class="personalquestion"><h2>${eventQuestion(ev)}</h2><p>${QUESTIONCOPY[ev.id].why}</p><div class="answers">${['Yes','Not yet','Not sure'].map(x=>`<button class="chip ${a===x?'on':''}" aria-pressed="${a===x}" onclick="setAnswer('${ev.id}','${x}')">${x}</button>`).join('')}</div>${a?`<div class="feedback" role="status">${a==='Yes'?QUESTIONCOPY[ev.id].yes:a==='Not yet'?'We’ll keep preparation visible. This doesn’t mark a skill as late.':'We’ll keep the guidance general. You can update this or ask your pediatrician.'}</div><button class="textlink" onclick="setAnswer('${ev.id}',null)">Clear answer</button>`:''}</section>`}
function personalizePage(){const age=actualMonth();return backButton()+`<div class="eyebrow">Optional updates</div><h1>What’s new<br>for ${name()}?</h1><p class="personal-intro">Update what you’re seeing to get feeding, sleep and home guidance that fits.</p>${safetyMovementSelector()}${age>=4?feedingStagePicker():''}<button class="guide-resource-row" onclick="openPage('topic:Sleep')"><span class="guide-resource-mark">${icon('sleep')}</span><span><b>Your sleep guide</b><small>Choose the guidance that fits</small></span><span aria-hidden="true">›</span></button><div class="deepfooter">Saved in this browser. Change these anytime; they don’t determine medical readiness.</div><div class="personaldone"><button class="primary" onclick="navigate('home')">Back to your month →</button></div>`;}

function contextualQuestion(id){if(id==='roll')return movementQuestion();if(!isCurrent())return '';const e=EVENTS.find(e=>e.id===id);return `<div class="deepcheck"><h3>${eventQuestion(e)}</h3><p class="hint">${QUESTIONCOPY[id].why} Optional.</p><div class="answers">${['Yes','Not yet','Not sure'].map(a=>`<button class="chip ${answers[id]===a?'on':''}" onclick="setAnswer('${id}','${a}')">${a}</button>`).join('')}</div>${answers[id]?`<button class="textlink" onclick="setAnswer('${id}',null)">Undo answer</button>`:''}</div>`}
function handyResource(id,reason){const r=RESOURCE[id];return `<button class="deepresource" onclick="openPage('resource:${id}')"><div class="eyebrow">Keep this handy</div><h3>${r.title}</h3><p>${reason||r.use}</p><div class="costline"><span>${r.cost}${r.commercial?' · Optional':''}</span><span>Why this source ↗</span></div></button>`}
function categoryPageBeforeRework(t){if(t==='Feeding')return feedingJourney();const s=stageSnapshot(t),dm=developmentMonth(),current=isCurrent(),started=current&&answers.solids==='Yes',tooth=current&&answers.tooth==='Yes',moving=current&&answers.crawl==='Yes';let title=s.title,intro=s.body,sections=[],question='',resources=[],faq=[],call='',source='',tone='#edf0df';
if(t==='Feeding'){tone='#f4eddb';question=month>=4?'solids':'';source=month<4?GUIDES.newborn.url:RESOURCE.readiness.url;
if(month<4){title='Milk, cues<br>and getting familiar.';sections=[['Notice the cues','Turning toward a feed can show hunger. Closing the mouth or turning away can signal fullness.'],['Support belongs here','Questions about feeding or growth are a reason to ask your pediatrician, not something to figure out alone.']];resources=[['care','For everyday feeding questions and pediatric guidance.']]}
else if(started){title='First tastes.<br>A little at a time.';intro=milkName()+' is still important. Foods add new tastes, textures and skills to explore.';sections=[['Watch your baby, not an amount','Opening for food or turning away can help you recognize hunger and fullness.'],['Preparation is part of feeding','Use an age-appropriate food-preparation guide. A food’s shape and texture matter.'],['Make room for your questions','Ask your pediatrician about allergens and individual feeding needs.']];resources=[['solids','Look up how to prepare a particular food before serving it. The database is free; guided plans are optional.']];faq=[['Do I need to choose baby-led or purees?','Talk through the options with your pediatrician. Readiness, nutrition and safe food preparation matter whichever approach you choose.']]}
else {title='Before the<br>first bites.';intro='Starting solids is generally around six months. You’re getting familiar with readiness—not racing toward a date.';sections=[['What readiness looks like','Look for head control, supported sitting and being able to move food back to swallow. Interest in your plate alone isn’t enough.'],['What you can do now','Bring your readiness questions to the pediatrician and get familiar with an upright, supported place for meals.']];resources=[['readiness','Start here for the readiness signs and the basics of introducing food.'],['solids','When a specific food question comes up, use the free food-preparation database. You don’t need to work through a course first.']];faq=[['What if my baby was born early?','Discuss timing with your pediatrician. Adjusted age helps describe development, but a date alone doesn’t establish feeding readiness.']]}
call='Ask about persistent feeding difficulty, growth concerns or uncertainty about readiness. Your pediatrician can tailor timing and feeding support.';
}else if(t==='Development'){question=dm>=3?'roll':'';source=developmentBrief(dm).src;title=dm<=2?'Little signs<br>of connection.':dm<=4?'More ways<br>to respond.':dm<=6?'Skills taking<br>shape.':dm<=9?'A bigger<br>little repertoire.':'So much<br>to communicate.';intro='Use this stage as a reference for what you might notice. Your baby’s observations belong alongside it.';const skill=dm<=2?['Connection','Attention to faces and voices, with early smiles and responses.']:dm<=4?['Sounds and control','The four-month guide includes cooing, holding toys and steadier head control.']:dm<=6?['Movement','The six-month guide includes tummy-to-back rolling and leaning on hands while sitting.']:dm<=9?['Movement and sounds','The nine-month guide includes sitting without support, transferring objects and repeated babbles.']:['Gestures and movement','The first-birthday guide includes waving, familiar names, pulling up and moving along furniture.'];sections=[skill,['In ordinary play',dm<=6?'Respond to a sound and leave a pause. Offer supervised floor time and follow what interests your baby.':'Join a familiar game, name what they notice and leave room for a response.']];if(current&&answers.roll==='Yes')sections.push(['You mentioned rolling','Make room for supervised movement play. Sleep and changing-space safety remain important as movement changes.']);resources=[['cdc','Use the stage’s examples or videos when you’re unsure what a skill looks like.']];faq=[['What if I haven’t noticed a skill?','Tell your pediatrician what you’re seeing. These guides aren’t diagnostic tests, and “not yet” should never hide a concern.']];call='Discuss missed milestones, any loss of a previously used skill, or concerns about development. Don’t wait for the next app update.';
}else if(t==='Sleep'){tone='#eeebf4';source=RESOURCE.aap.url;title=answers.sleepNeed==='Sleep has changed'&&current?'Nights feel<br>different.':month<3?'Little stretches.<br>Day and night.':'Understanding<br>your nights.';intro=month<3?'Newborn sleep comes in short stretches. A regular pattern takes time to develop.':'Sleep cycles become more regular around four months, but babies’ patterns and needs vary.';sections=[['Start with what’s changed','Consider feeds, comfort and signs of illness alongside development. Waking alone doesn’t identify the cause.'],['Keep one familiar anchor','Soft voices and gentle care can keep nights quiet. You can respond to your baby’s needs.']];resources=[['aap','For pediatric sleep basics and safe-sleep guidance.']];if(current&&answers.sleepNeed==='I want more support')resources.push(['cara','If you want a structured course, review its approach and costs. It’s optional commercial support.']);faq=[['Do we have to sleep train?','Ahead doesn’t assume you will. If you want a structured approach, compare its method and discuss feeding or medical concerns with your pediatrician.'],['Where can I find more structured support?','Taking Cara Babies is one commercial option to evaluate. It isn’t a required stage or an Ahead-approved course.']];call='Contact your pediatrician if a sleep change accompanies illness, feeding concerns or something that worries you.';
}else if(t==='Health'){tone='#f4e9e2';question=month>=3?'tooth':'';source=tooth?RESOURCE.toothcare.url:month>=4?RESOURCE.teething.url:RESOURCE.care.url;
if(tooth){title='A first tooth.<br>A new little routine.';intro='You mentioned a tooth has arrived. Tooth care becomes useful now, whatever month it happens.';sections=[['Brushing starts with the first tooth','Brush twice daily using a rice-grain-sized smear of fluoride toothpaste.'],['Make the dental connection','Arrange a first dental visit when the tooth appears, and no later than the first birthday.']];resources=[['toothcare','For first-tooth brushing, fluoride questions and the first dental visit.']]}
else if(month>=4&&month<=10){title='Could this<br>be teething?';intro='Chewing and drool may make you wonder. First teeth often appear between six and ten months, with individual variation.';sections=[['What you may notice','Tender gums, extra drool and chewing can accompany teething.'],['What may help','A clean-finger gum massage or a suitable solid teething toy can offer comfort.']];resources=[['teething','For symptom distinctions and comfort options, including remedies to avoid.']]}
else {title='Your questions<br>belong here.';intro='Keep feeding, growth and development questions close for your baby’s care team.';sections=[['Bring everyday observations','Share changes or concerns with your pediatrician rather than waiting until they feel big enough.']];resources=[['care','For pediatric information on everyday health and care.']]}
faq=[['Can a fever just be teething?','Don’t attribute a fever to teething. Ask your pediatrician about fever or other concerning symptoms.']];call='Contact your pediatrician about symptoms that concern you. Fever, diarrhea or unusually frequent crying shouldn’t automatically be attributed to teeth.';
}else if(t==='Safety'){question=dm>=6?'crawl':dm>=3?'roll':'';source=dm<7&&!moving?RESOURCE.safesleep.url:RESOURCE.cdc.url;title=moving?'See the room<br>from their level.':dm<3?'Every sleep,<br>safely.':dm<7?'New movement.<br>Useful changes.':'A bigger reach.<br>A fresh look.';intro=moving?'You mentioned crawling or scooting. The space your baby can explore has changed.':'Safety guidance belongs here before a new skill appears, as well as afterward.';sections=dm<7&&!moving?[['Sleep setup stays simple','Place baby on their back on a firm, flat sleep surface with a fitted sheet and no soft objects.'],['Don’t wait for a completed roll','Stop swaddling when you notice signs of trying to roll. A “not yet” answer doesn’t remove this guidance.']]:[['Start with the play space','Look from floor level at what can be reached or pulled. Revisit the space when movement changes.'],['Small changes, connected to the skill','Keep unsafe objects out of reach and review a trusted safety guide for the area your baby can explore.']];resources=[[dm<7&&!moving?'safesleep':'cdc',dm<7&&!moving?'For the exact sleep recommendations and what changes around rolling.':'For stage-related safety and exploration tips.']];call='For a possible injury or exposure, seek appropriate medical help rather than waiting for app guidance.';
}else {tone='#f0efe1';source=RESOURCE.aap.url;title='A little rhythm.<br>Room for real life.';intro='You don’t need a perfect schedule to make parts of the day feel familiar.';sections=[['Daytime is for connection','Talking and playing can fit into feeding, changing and ordinary awake moments.'],['Let nights feel different','Keep voices soft and nighttime care quiet and gentle.'],['Follow the cues you see','Your baby’s comfort and your family’s needs help shape what works.']];resources=[['aap','For pediatric sleep guidance that can inform your nighttime rhythm.']];call='Bring concerns about sleep, feeding or wellbeing to your pediatrician.';}
const context=current?(t==='Feeding'&&answers.solids?`Solids: ${answers.solids.toLowerCase()}`:t==='Health'&&tooth?'First tooth: here':t==='Safety'&&moving?'Crawling or scooting: yes':profile.feed&&t==='Feeding'?profile.feed:'Matched to age and your check-ins'):'A stage preview; your answers apply to the current month';
return `<div class="deeptop">${backButton()}<button class="savequiet" onclick="saveTopic('${t}')">${icon('saved')}${saved.includes('topic:'+t)?'Saved':'Save'}</button></div><header class="deepheader" style="--deepbg:${tone}"><div class="deepicon">${icon(TOPICS.find(x=>x[0]===t)[1])}${t} · ${monthLabel(month)}</div><h1>${title}</h1><p>${intro}</p></header><div class="contextbar"><span>${name()} · ${esc(context)}</span>${current?'<button onclick="openPage(&quot;personalize&quot;)">Edit</button>':''}</div><section class="deepsection"><h2>${t==='Development'?'What you might notice':'What matters now'}</h2>${sections.map(([a,b])=>`<div class="insightline"><h3>${a}</h3><p>${b}</p></div>`).join('')}</section>${question?contextualQuestion(question):''}<section class="deepsection"><h2>Where to turn</h2>${resources.map(([id,reason])=>handyResource(id,reason)).join('')}${t==='Sleep'&&!(current&&answers.sleepNeed==='I want more support')?'<button class="textlink" onclick="openPage(&quot;resource:cara&quot;)">Explore optional structured sleep support →</button>':''}</section>${faq.map(([q,a])=>`<details class="deepquestion"><summary>${q}<span>＋</span></summary><p>${a}</p></details>`).join('')}<section class="deepcall"><h3>When to ask your pediatrician</h3><p>${call}</p></section><div class="deepfooter"><a href="${source}" target="_blank" rel="noopener">${source.includes('cdc.gov')?'CDC':'AAP · HealthyChildren'} source ↗</a><div class="deepfootlinks"><button onclick="openPage('trust')">Why this source</button><button onclick="openPage(&quot;personalize&quot;)">Update check-ins</button></div><p class="hint">Prototype content</p></div>`;}



let selectedFeedingCue=null,selectedMealTip=null;
const CUES={sit:['Sits with support','Upright, with support','Your baby can sit upright with support. Discuss this alongside the other signs with your pediatrician.'],head:['Head stays steady','Head and neck control','Notice whether your baby controls their head and neck while supported upright. Bring uncertainty to your pediatrician.'],open:['Opens for food','Responds to an offer','Opening the mouth when food is offered can be a readiness sign. Watching your plate alone doesn’t establish readiness.'],swallow:['Moves food to swallow','More than interest','Moving food back and swallowing, rather than pushing it straight out, is another sign. Ask your pediatrician how to interpret it; don’t run your own feeding test.']};
function babySvg(k){const face=`<circle cx="50" cy="25" r="16" fill="#ecd4b5"/><path d="M43 23h.2m13.5 0h.2" stroke="#637052" stroke-width="2.6" stroke-linecap="round"/><path d="M47 12q5-6 7 0" stroke="#b5a17c" stroke-width="1.5" stroke-linecap="round"/>`;const body=`<path d="M33 49q17-15 34 0v15H33Z" fill="#bdcda4"/>`;let content='';if(k==='sit')content=`<path d="M28 22v40h45V22" stroke="#c8b88c" stroke-width="4" stroke-linecap="round"/>${body}${face}<path d="m38 45 12 11 12-11M50 56v8" stroke="#7a8f65" stroke-width="2"/><path d="M23 52h55" stroke="#c8b88c" stroke-width="5" stroke-linecap="round"/>`;else if(k==='head')content=`${body}${face}<path d="M47 32q3 3 6 0" stroke="#9a8c6a" stroke-width="1.5" stroke-linecap="round"/><path d="M24 17v17m-4-13 4-4 4 4m44-4v17m-4-4 4 4 4-4" stroke="#a3b58d" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>`;else if(k==='open'||k==='swallow')content=`${body}${face}${k==='open'?'<ellipse cx="50" cy="32" rx="3" ry="4" fill="#ac8b72"/>':'<path d="M47 32q3 3 6 0" stroke="#9a8c6a" stroke-width="1.5" stroke-linecap="round"/>'}<ellipse cx="73" cy="32" rx="6" ry="3" fill="#d9c895"/><path d="M79 32h12" stroke="#a6b78c" stroke-width="3" stroke-linecap="round"/>${k==='swallow'?'<path d="M50 42v9m-3-3 3 3 3-3" stroke="#96a77e" stroke-width="1.5" stroke-linecap="round"/>':''}`;else if(k==='milk')content=`<path d="M49 7C46 15 30 30 30 43a19 19 0 0 0 38 0C68 30 52 15 49 7Z" fill="#d7dfbd"/><path d="M39 46q1 8 9 9" stroke="#fffdf1" stroke-width="3" stroke-linecap="round"/>`;else if(k==='food')content=`<path d="M23 35c0 22 13 28 29 28s27-8 27-28H23Z" fill="#cfbc85"/><ellipse cx="51" cy="35" rx="28" ry="5" fill="#e9dab0"/><path d="M62 29V10" stroke="#8b9f71" stroke-width="3" stroke-linecap="round"/><ellipse cx="62" cy="11" rx="5" ry="8" fill="#a9b98e"/>`;else content=`${face}${body}<path d="M45 32q5 5 10 0" stroke="#9e8966" stroke-width="1.5" stroke-linecap="round"/>`;return `<svg class="cueillustration" viewBox="0 0 100 75" fill="none" aria-hidden="true">${content}</svg>`}
function chooseCue(k){selectedFeedingCue=selectedFeedingCue===k?null:k;const y=window.scrollY;render();window.scrollTo(0,y)}
function readinessVisual(){return `<section class="calm-section"><h2>Signs to look for.</h2><p class="cue-help">Notice the cues. Tap one for what it means.</p><div class="cuegrid">${Object.entries(CUES).map(([k,v])=>`<button class="cuecard ${selectedFeedingCue===k?'isopen':''}" aria-expanded="${selectedFeedingCue===k}" onclick="chooseCue('${k}')">${babySvg(k)}<b>${v[0]}</b><span class="cuehint">What this means ＋</span></button>`).join('')}</div>${selectedFeedingCue?`<div class="cueanswer" role="status"><h3>${CUES[selectedFeedingCue][1]}</h3><p>${CUES[selectedFeedingCue][2]}</p><button onclick="chooseCue('${selectedFeedingCue}')">Close</button></div>`:''}<p class="cue-help">Your pediatrician can help you decide whether these signs mean it’s time to start.</p>${profile.early?'<p class="calm-early">Born early? Discuss individual timing. Adjusted age alone doesn’t decide readiness.</p>':''}</section>`}
const MEAL={seat:'Get familiar with an upright, supported place for meals. Follow the seat’s safety instructions.',near:'Stay close and supervise eating. This illustration is a simple reminder, not a complete safety checklist.',food:'Check preparation for the particular food and your baby’s developmental ability. A database can help when that question comes up.'};
function mealVisual(){return `<section class="calm-section"><h2>A little place for first bites.</h2><div class="mealvisual"><svg class="meal-scene" viewBox="0 0 320 120" fill="none" aria-hidden="true"><ellipse cx="155" cy="109" rx="82" ry="6" fill="#e0dfcb"/><path d="M117 24v49h65V24" stroke="#c1b28a" stroke-width="6" stroke-linecap="round"/><path d="m123 77-7 30m59-30 8 30" stroke="#b8ab88" stroke-width="4" stroke-linecap="round"/><path d="M128 58q22-12 44 0v21h-44Z" fill="#b9cba0"/><circle cx="150" cy="34" r="19" fill="#ecd4b5"/><path d="M142 32h.2m15 0h.2" stroke="#637052" stroke-width="2.8" stroke-linecap="round"/><path d="M146 42q4 3 8 0" stroke="#a88d6b" stroke-width="1.8" stroke-linecap="round"/><path d="m135 57 15 13 15-13m-15 13v9" stroke="#7c9068" stroke-width="2"/><path d="M105 75h91" stroke="#d4c494" stroke-width="8" stroke-linecap="round"/><path d="M170 64q0 10 10 10t10-10Z" fill="#9eae7c"/><path d="M228 78V57q0-8-7-8t-7 8v38" stroke="#c9ae95" stroke-width="9" stroke-linecap="round"/><circle cx="221" cy="27" r="12" fill="#e0c4a4"/><path d="M65 34h18m-5-5 5 5-5 5M254 78h-15" stroke="#b5bd9c" stroke-width="1.5" stroke-linecap="round"/></svg><div class="meal-chips">${[['seat','Supported seat'],['near','Stay close'],['food','Check the food']].map(([k,l])=>`<button onclick="selectMealTip('${k}')" aria-expanded="${selectedMealTip===k}">${l} ＋</button>`).join('')}</div>${selectedMealTip?`<div class="cueanswer" role="status"><p>${MEAL[selectedMealTip]}</p></div>`:''}</div></section>`}
function selectMealTip(k){selectedMealTip=selectedMealTip===k?null:k;const y=window.scrollY;render();window.scrollTo(0,y)}
function tableVisual(){return `<section class="calm-section"><h2>At the table.</h2>${[['milk','Milk stays in the picture',milkName()+' remains important alongside foods.'],['food','Preparation follows the skill','Match food texture and preparation to development. Always supervise eating.'],['smile','Follow their response','Opening for food or closing the mouth can help show hunger and fullness.']].map(([k,t,d])=>`<div class="visual-takeaway">${babySvg(k)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</section>`}
function questionResource(mode){if(mode==='milk')return `<section class="calm-resource"><div class="eyebrow">A useful place to turn</div>${handyResource('care','Pediatric information for everyday feeding and baby-care questions.')}</section>`;return `<section class="resource-question"><button class="question-main" onclick="openPage('resource:solids')"><svg class="food-art" viewBox="0 0 50 65" fill="none" aria-hidden="true"><path d="M25 3C18 3 4 30 4 43a21 21 0 0 0 42 0C46 30 32 3 25 3Z" fill="#bbcc98"/><path d="M25 9C19 9 10 32 10 43a15 15 0 0 0 30 0C40 32 31 9 25 9Z" fill="#e5ebc9"/><circle cx="25" cy="43" r="9" fill="#b79870"/></svg><div><div class="eyebrow">When you’re wondering…</div><h3>“How do I<br>serve this?”</h3><p>Solid Starts · Food preparation lookup</p></div></button><div class="resource-mini"><span>Free database · Paid plans optional</span><button onclick="openPage('resource:solids')">Why this source?</button></div>${['foods','stage'].includes(mode)?'<a class="examplelink" href="https://solidstarts.com/foods/avocado/" target="_blank" rel="noopener">See an avocado example ↗</a>':'<div class="examplelink" style="color:#869174">Handy when first foods begin.</div>'}</section>`}

function feedingJourney(){const current=isCurrent(),a=current?answers.solids:undefined,started=a==='Yes',milk=milkName(),mode=feedingState();const title=mode==='foods'?'First tastes.<br>Finding your way.':mode==='stage'?'Foods, milk<br>and growing skills.':mode==='milk'?'Milk feeds.<br>Learning their cues.':'Getting ready<br>for first bites.';const intro=mode==='foods'?`${milk} remains important as new tastes and feeding skills enter the picture.`:mode==='stage'?'Foods and milk are part of this stage. Guidance can follow whether your baby has started solids.':mode==='milk'?`${milk} is the food for this stage. Feeding cues and growth help you and your care team understand how it’s going.`:'Solids generally begin around six months, with developmental readiness. For now, get familiar with what to notice.';let h=`<div class="feeding-calm"><div class="deeptop">${backButton()}<button class="savequiet" onclick="saveTopic('Feeding')">${icon('saved')}${saved.includes('topic:Feeding')?'Saved':'Save'}</button></div><header class="feedinghero"><svg class="feedingart" viewBox="0 0 60 70" fill="none" aria-hidden="true"><path d="M18 30c0 13 8 19 23 19s18-8 18-19H18Z" fill="currentColor"/><path d="M25 54h25M33 19V3m0 0c-6 0-9 3-9 7s3 7 9 7 9-3 9-7-3-7-9-7Z" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><div class="eyebrow">Feeding · ${monthLabel(month)}</div><h1>${title}</h1><p>${intro}</p></header>`;
if(current&&month>=4)h+=`<details class="calm-personalize"><summary>${started?'Showing first-food guidance. ':a==='Not yet'?'Showing preparation guidance. ':a==='Not sure'?'Not sure about solids yet? ':''}<span>${a?'Change answer':'Already started solids?'}</span></summary><p class="hint">Has ${name()} started solids? Your answer changes this guidance, not a readiness assessment.</p><div class="answers">${['Yes','Not yet','Not sure'].map(x=>`<button class="chip ${a===x?'on':''}" aria-pressed="${a===x}" onclick="setAnswer('solids','${x}')">${x}</button>`).join('')}</div>${a?`<button class="textlink" onclick="setAnswer('solids',null)">Clear answer</button>`:''}</details>`;else h+='<div style="height:25px"></div>';
if(mode==='prep'){h+=`${readinessVisual()}${mealVisual()}<div class="calm-extra"><details><summary>What should I ask the pediatrician? <span class="plus">＋</span></summary><p class="copy-q">“Based on my baby’s head control, sitting and feeding skills, are they ready to start?”</p><button onclick="copyFeedingQuestion(this)">Copy question</button><div id="questionCopy" class="questioncopy" role="status"></div></details><details><summary>What if I’m not sure about a sign? <span class="plus">＋</span></summary><p>Use the CDC’s examples and videos, and share your observations with your pediatrician. “Not sure” keeps preparation visible without labeling your baby as behind.</p><a class="smallsource" href="${RESOURCE.readiness.url}" target="_blank" rel="noopener">See the CDC’s readiness guidance ↗</a></details></div>`;
}else if(mode==='foods'||mode==='stage'){h+=`${tableVisual()}<div class="calm-extra"><details><summary>What about allergens? <span class="plus">＋</span></summary><p>Ask your pediatrician about introducing common allergens. Severe eczema or an egg allergy can change advice for peanut introduction.</p></details><details><summary>Purees, finger foods or a mix? <span class="plus">＋</span></summary><p>Discuss options with your care team. Safe preparation and textures that fit development matter whichever approach you choose.</p></details><details><summary>Is there a right order for foods? <span class="plus">＋</span></summary><p>For most children, the AAP does not require a particular food order. Ask about your baby’s needs and allergen introduction.</p></details></div>`;
}else{h+=`<section class="calm-section"><h2>Notice their cues.</h2><div class="calm-fact"><h3>Looking for a feed</h3><p>Hands toward the mouth, turning toward a breast or bottle, and lip movements can signal hunger.</p></div><div class="calm-fact"><h3>Showing they’ve had enough</h3><p>Closing the mouth or turning away can signal fullness. Interpret feeding alongside growth with your care team.</p></div></section><section class="calm-section"><h2>Support belongs here.</h2><p>If feeding feels painful, difficult or worrying, ask for help. You don’t have to figure it out alone.</p></section>`}
h+=`${questionResource(mode)}<section class="calm-call"><h3>When to ask your pediatrician</h3><p>Ask about readiness uncertainty, persistent feeding difficulty or concerns about growth. Your care team provides individual feeding advice.</p></section><div class="calm-footer"><a href="${mode==='milk'?'https://www.cdc.gov/act-early/milestones/2-months.html':RESOURCE.readiness.url}" target="_blank" rel="noopener">CDC guidance behind this screen ↗</a><p>Prototype</p></div></div>`;return h;}

async function copyFeedingQuestion(button){const txt='Based on my baby’s head control, sitting and feeding skills, are they ready to start?';try{await navigator.clipboard.writeText(txt);$('#questionCopy').textContent='Copied. Keep it for your next conversation.'}catch{$('#questionCopy').innerHTML=`<textarea readonly aria-label="Question to copy" style="width:100%;padding:10px;font:inherit;border:1px solid #dce3cf;border-radius:10px">${txt}</textarea><p class="hint">Select and copy this question.</p>`}}

function originalHomeAtlas(){const dm=developmentMonth(),b=developmentBrief(dm);const focus=monthlyFocus(),title=focus.title;return `<div class="homemeta"><b>${name()}’s first year</b><span>${profile.example?'Example · ':''}${monthLabel(month)}</span></div><nav class="monthstrip" aria-label="Browse your baby’s year">${STAGES.map((s,i)=>`<button class="month ${month===i?'active':''} ${i===actualMonth()?'current':''}" onclick="setMonth(${i})" aria-label="${monthLabel(i)}${i===actualMonth()?', current age':''}" aria-pressed="${month===i}"><b>${i===0?'N':i}</b><span>${i===0?'newborn':'mo'}</span></button>`).join('')}</nav>${profile.early?`<div class="monthinfo"><span>Development & play: ${monthLabel(dm)} adjusted</span><button class="textlink" onclick="openPage('age-context')">About age</button></div>`:''}<section class="home-summary"><div class="home-summary-heading"><div class="home-month-eyebrow">What matters this month</div><h1>${title}</h1></div><span class="home-summary-art" aria-hidden="true">${homeMonthArt(month)}</span><p class="heroanswer">${focus.body}</p><div class="home-summary-spectrum" aria-hidden="true">${TOPICS.map(([topic])=>`<span style="background:${YEAR_PALETTES[topic].bg}"></span>`).join('')}</div></section><div class="atlashead"><h2>Explore this stage.</h2>${isCurrent()?`<button class="tailor" onclick="openPage(&quot;personalize&quot;)">Update baby’s stage</button>`:''}</div><section class="atlas" aria-label="All aspects of baby care">${TOPICS.map(([t,i])=>{const x=stageSnapshot(t);return `<button class="atlascard" data-cat="${t}" style="${yearTheme(t)}" onclick="openPage('topic:${t}')"><span class="cardtop"><span class="home-tile-art" aria-hidden="true">${yearIllustration(t,1)}</span><span class="categoryname">${displayTopic(t)}</span></span><h3>${x.title}</h3><p>${x.body}</p><span class="smallarrow">${icon('arrow')}</span></button>`}).join('')}</section>${homePreparation()}<button class="year-home-link" onclick="openPage('year')"><span>See a category across the year</span><span aria-hidden="true">↗</span></button><div class="sourcenote">${icon('safety')}Sources explained. No paid placements.</div><div class="quiet-bottom"><button onclick="openPage('trust')">How we choose guidance</button></div><div class="foot" style="margin-top:2px">Prototype</div>`}


const WORLD_STORIES=[
['A familiar voice<br>in a new world.','Your voice and touch bring something familiar to a very new day. You may notice your baby settling when you speak or hold them.','Watch their cues; connection can happen in ordinary care.'],
['Your face is<br>worth studying.','Looking at your face and watching you move are part of getting to know their surroundings. Small responses may become easier to notice.','Talk during a change or a cuddle, and pause when they need a break.'],
['A smile can<br>start something.','A smile from you may bring one back. Your baby is finding early ways to respond and connect with the people close to them.','Respond to their sounds and expressions, leaving space for a reply.'],
['A sound from you.<br>A sound back.','Little sounds can become an exchange. Your baby may turn toward your voice and find ways to keep your attention.','Copy a sound and wait. That pause gives them a turn.'],
['Those hands<br>are fascinating.','Hands are something to look at, move and bring closer. Your baby is exploring what they can do with them.','Offer safe, easy-to-hold toys during supervised play.'],
['A whole world<br>in their hands.','A toy may go straight from hand to mouth. Reaching, holding and mouthing are ways your baby explores an object.','Offer safe objects while you supervise and follow their interest.'],
['Again?<br>That’s a discovery.','A toy falls, you pick it up, and it happens again. Simple back-and-forth games give your baby something to notice and repeat.','Join in an ordinary game; it doesn’t need a special activity.'],
['One hand.<br>Then the other.','Passing and studying an object creates new ways to explore it. You may notice more deliberate handling during play.','Give them space to handle safe toys, rather than doing every step for them.'],
['Where you go<br>matters more.','Your baby may pay more attention when you leave or when someone unfamiliar comes close. Their reactions can become more noticeable.','Familiar voices and everyday games give you ways to reconnect.'],
['Out of sight.<br>Still interesting.','A dropped or partly hidden object can become something to look for. Play may now include noticing where things go.','Hide a toy while they watch and see what they do.'],
['Little gestures.<br>Shared meaning.','Gestures and familiar sounds can carry a message between you. Your baby may be finding more ways to join in.','Name what they notice and respond to attempts to communicate.'],
['The favorite game?<br>Again, please.','Familiar games and repeated sounds give your baby another chance to take part. Repetition is part of the experience.','Follow their interest in a familiar book or game.'],
['So many ways<br>to say hello.','A wave, a familiar name or a shared game can become a little conversation. New gestures add to the ways you understand each other.','Respond to gestures and words, and keep the back-and-forth going.']
];
function developmentMonthlyLabel(dm){return ['Faces & familiar voices','Getting to know your face','Smiles & early sounds','Sounds back & forth','Hands & steadier head control','Reaching, holding & exploring','Laughs, sounds & new movement','Passing toys between hands','Familiar faces & reactions','Sitting & finding things','Gestures & shared meaning','Taking turns in familiar games','Waves, words & new movement'][clamp(dm)];}
function developmentBrief(dm){const v=WORLD_STORIES[clamp(dm)],ref=dm<=2?2:dm<=4?4:dm<=6?6:dm<=9?9:12;return {title:v[0],body:v[1],small:v[2],src:`https://www.cdc.gov/act-early/milestones/${ref===12?'1-year':ref+'-months'}.html`,label:'CDC developmental guidance'}}
function feedingState(){if(isCurrent()&&answers.solids==='Yes')return 'foods';if(month<4)return 'milk';if(month<7||(isCurrent()&&month<12&&answers.solids!=='Yes')||(isCurrent()&&['Not yet','Not sure'].includes(answers.solids)))return 'prep';return 'stage'}
const WELL_VISITS=[0,1,2,4,6,9,12];function visitForMonth(){const next=WELL_VISITS.find(n=>n>=month);return {age:next??12,now:WELL_VISITS.includes(month)}}
RESOURCE.visits={...RESOURCE.care,title:'AAP · Well-child visits',use:'For “what is this checkup for?”',when:'Before routine visits, to bring feeding, growth, development and safety questions.',url:'https://www.healthychildren.org/English/family-life/health-management/Pages/Well-Child-Care-A-Check-Up-for-Success.aspx',evidence:'The AAP describes its Bright Futures preventive care schedule and the role of regular visits.',refs:[['AAP visit schedule and purpose','https://www.healthychildren.org/English/family-life/health-management/Pages/Well-Child-Care-A-Check-Up-for-Success.aspx']]};
RESOURCE.play={...RESOURCE.care,title:'AAP · Everyday play',use:'For small ways to play and connect at this stage.',when:'When you want an age-relevant idea that fits into an ordinary day.',url:'https://www.healthychildren.org/English/ages-stages/baby/Pages/How-Active-is-Your-Baby.aspx',evidence:'Age-grouped parent education from the American Academy of Pediatrics.',refs:[['AAP play and movement ideas','https://www.healthychildren.org/English/ages-stages/baby/Pages/How-Active-is-Your-Baby.aspx']]};
function milestoneReference(){const dm=developmentMonth();return dm<=2?2:dm<=4?4:dm<=6?6:dm<=9?9:12}
function skillCards(){const r=milestoneReference();const skills={2:[['Looking and responding','Watches you move and responds to your face or voice.'],['Early movement','Lifts the head during tummy time and moves arms and legs.']],4:[['Sounds back to you','Coos and makes sounds in response to your voice.'],['Steadier head control','Holds the head steady while being held.']],6:[['Rolling from tummy to back','Turns from lying on their tummy onto their back. This is one direction, not the same as rolling both ways.'],['Sitting with hands for balance','Leans on their hands while sitting. This differs from sitting without support.']],9:[['Sitting without support','Sits without needing support and can get into sitting.'],['More sounds and hand skills','Makes repeated babbles and moves objects between hands.']],12:[['Gestures and familiar names','Waves and uses a familiar name for a parent.'],['Pulling up and moving along furniture','Pulls to stand and takes steps while holding furniture.']]};return skills[r].map(([t,d])=>`<div class="skill-card"><h3>${t}</h3><p>${d}</p><span class="skillwhen">CDC reference: by ${r} months</span></div>`).join('')}
function movementQuestion(){if(!isCurrent())return '';const opts=['Not yet','Trying to roll','Tummy to back','Back to tummy','Both ways','Not sure'];return `<details class="calm-personalize"><summary><span>${answers.rollDirection?'Rolling: '+esc(answers.rollDirection)+' · Edit':'What movement are you noticing?'}</span></summary><p class="hint">This updates movement-related safety guidance and the rolling reminder in Sleep. All four Development areas stay visible; this isn’t a milestone score.</p><div class="journeychoices">${opts.map(v=>`<button class="${answers.rollDirection===v?'on':''}" onclick="setMovement('${v}')">${v}</button>`).join('')}</div>${answers.rollDirection?'<button class="textlink" onclick="setMovement(null)">Clear answer</button>':''}</details>`}
function setMovement(v){markStage('movement');if(v){answers.rollDirection=v;answers.roll=['Tummy to back','Back to tummy','Both ways'].includes(v)?'Yes':v==='Not sure'?'Not sure':'Not yet'}else{delete answers.rollDirection;delete answers.roll}persist();const y=window.scrollY;render();window.scrollTo(0,y)}
function openSavedTopic(t){month=actualMonth();openPage('topic:'+t)}function openSavedGuide(k){month=actualMonth();openGuide(k)}
function sleepChoices(){if(!isCurrent())return '';return `<details class="calm-personalize"><summary><span>${answers.sleepChange?esc(answers.sleepChange)+' · Change':'Has something changed with sleep?'}</span></summary><div class="journeychoices">${['More night waking','Shorter naps','Harder settling','Just exploring'].map(v=>`<button class="${answers.sleepChange===v?'on':''}" onclick="setAnswer('sleepChange','${v}')">${v}</button>`).join('')}</div></details>`}
function updatedSnapshot(t){const s=stageSnapshotBeforeRework(t),dm=developmentMonth(),r=milestoneReference();
if(t==='Development'){s.body=dm<=2?'Watch for responses to your face and voice. Skills emerge over time.':dm<=4?'Notice sounds back to you and steadier head control.':dm<=6?'Your baby may be working toward tummy-to-back rolling and sitting with hands for balance. Most babies do these by six months.':dm<=9?'Sitting without support and repeated babbles are skills most babies do by nine months.':'Waving and pulling up are skills most babies do by the first birthday.';s.status=dm<r?'Developing toward '+r+' months':'Reference: by '+r+' months';}
if(t==='Feeding'){const f=feedingState();s.title=f==='milk'?'Follow feeding cues':f==='prep'?'Before the first bites':f==='foods'?'First tastes':'Foods & milk';s.body=f==='milk'?'Hunger and fullness cues help you understand feeds.':f==='prep'?'Learn readiness signs and prepare for a conversation with your pediatrician.':f==='foods'?milkName()+' remains important alongside foods.':'Food preparation and feeding cues matter alongside milk feeds.';s.status=f==='prep'?'Preparing':f==='foods'?'From your check-in':'At this stage';}
if(t==='Health'&&!(isCurrent()&&answers.tooth==='Yes')){const v=visitForMonth();s.title=v.age===0?'The first checkup':v.age+'-month visit';s.body=v.now?'A routine visit is a place for growth, development, feeding and vaccine questions.':'The next checkup covers growth, development and feeding changes at this stage.';s.status=v.now?'Around this month':'Looking ahead';s.resource='visits'}
if(t==='Daily rhythm'){s.title=dm<3?'Feed, connect, rest':dm<6?'Room for play':dm<9?'Meals join the day':'Shared everyday moments';s.body=dm<3?'Follow cues through feeds, small awake moments and rest.':dm<6?'A familiar book or floor play can fit into ordinary awake time.':dm<9?'As foods begin, make room for supervised meals alongside milk, play and rest.':'Books, songs and everyday routines offer chances to join in.';s.resource='play'}
if(t==='Safety'&&isCurrent()&&answers.rollDirection==='Trying to roll'){s.title='Trying to roll';s.body='Stop swaddling at signs of trying to roll. Don’t wait for a completed roll.';s.status='From your check-in'}return s;}
function categoryRework(t){if(t==='Feeding')return feedingJourney();const snap=stageSnapshot(t),dm=developmentMonth(),ref=milestoneReference(),current=isCurrent(),tooth=current&&answers.tooth==='Yes';let title=snap.title,intro=snap.body,body='',resource=snap.resource,why='',source='',question='',call='',tone='#edf0df';
if(t==='Development'){title='Recognize the<br>little changes.';intro='Your baby may be working on these skills. “By six months,” for example, means most babies do a skill by that age—not that it starts then.';body=`<span class="reference-label">${dm<ref?'Developing toward '+ref+' months':'Reference point: by '+ref+' months'}${profile.early?' · adjusted age':''}</span>${skillCards()}${movementQuestion()}<section class="calm-section" style="margin-top:25px"><h2>In ordinary play.</h2><p>${dm<=4?'Copy a sound and pause for a reply. Give your baby supervised room to move.':dm<=6?'Offer supervised floor time and safe objects to reach for. Respond to their sounds and follow their cues.':'Join a familiar game, name what catches their interest and give them time to respond.'}</p></section>`;resource='cdc';why='See examples of a skill when words aren’t enough. Use the checklist as a reference for conversations, not a diagnosis.';source=developmentBrief(dm).src;call='Talk with your pediatrician about missed milestones, any loss of skills, or concerns. You don’t need to wait for the next app update.';}
else if(t==='Sleep'){tone='#eeebf4';title=current&&answers.sleepChange&&answers.sleepChange!=='Just exploring'?'When sleep<br>feels different.':month<3?'Little stretches.<br>Day and night.':'Making sense<br>of your nights.';intro=month<3?'Newborn sleep comes in short stretches. Regular sleep patterns take time.':'Sleep cycles become more regular around four months. That doesn’t predict exactly when or how your baby’s nights will change.';body=`${sleepChoices()}<section class="calm-section"><h2>${current&&answers.sleepChange&&answers.sleepChange!=='Just exploring'?'Start with what you notice.':'A useful starting point.'}</h2><div class="calm-fact"><h3>Consider the whole picture</h3><p>Notice whether waking comes with feeding needs, discomfort or illness. A calendar label alone can’t tell you the cause.</p></div><div class="calm-fact"><h3>Keep nighttime care gentle</h3><p>Use a soft voice and quiet care during feeds or changes. Respond to hunger, illness or a dirty diaper as needed.</p></div></section><details class="deepquestion"><summary>Do we need a sleep course?<span>＋</span></summary><p>No course is required by Ahead. If you want a structured approach, compare its method, fit and cost.</p><button class="textlink" onclick="openPage('resource:cara')">Explore optional sleep support →</button></details>`;resource='aap';why='Pediatric sleep basics, including safe sleep and nighttime care. More structured support is optional.';source=RESOURCE.aap.url;call='Contact your pediatrician if changes accompany illness, feeding or growth concerns, or something that worries you.';}
else if(t==='Health'){tone='#f4e9e2';const v=visitForMonth();title=tooth?'A first tooth.<br>And everyday care.':'Care through<br>this stage.';intro='Keep routine care and the questions that arise between visits in one place.';body=`<section class="calm-section"><h2>${v.age===0?'The first checkup':v.age+'-month well visit'}</h2><p>${v.now?'This is a routine visit age in the AAP schedule.':'The next routine visit in the AAP schedule is around this age.'} Your pediatrician may tailor the schedule.</p><div class="calm-fact"><h3>Bring what you’re seeing</h3><p>Growth, feeding, development, sleep and vaccines are all appropriate questions. You don’t have to wait for a concern to feel big.</p></div></section>${month>=3||tooth?`<section class="calm-section"><h2>${tooth?'A tooth is here.':'Teething may be on your mind.'}</h2><p>${tooth?'Start brushing twice daily with a rice-grain-sized smear of fluoride toothpaste. Arrange a first dental visit when a tooth appears, no later than the first birthday.':'Drooling and chewing can accompany teething, but don’t explain every symptom. Fever should not be attributed to teeth.'}</p>${contextualQuestion('tooth')}</section>`:''}<details class="deepquestion"><summary>Where can I check a teething question?<span>＋</span></summary><button class="textlink" onclick="openPage('resource:teething')">AAP signs and comfort guidance →</button></details>`;resource=tooth?'toothcare':'visits';why=tooth?'First-tooth brushing, fluoride and planning the dental visit.':'Understand the role and timing of routine checkups, with questions to bring.';source=RESOURCE[resource].url;call='Contact your pediatrician about symptoms that concern you. Don’t assume a fever or unusual symptoms are teething. Follow your care team’s instructions for urgent concerns.';}
else if(t==='Safety'){title='Before the skill.<br>And after it arrives.';intro='Preparation should not wait for a “yes” on a milestone check-in.';body=`<section class="calm-section"><h2>Sleep safety stays current.</h2><div class="calm-fact"><h3>Back, firm, flat and clear</h3><p>Place your baby on their back on a firm, flat sleep surface. Keep soft objects and loose bedding out.</p></div><div class="calm-fact"><h3>Trying to roll is enough</h3><p>Stop swaddling at signs of trying to roll. You don’t need to wait for a complete roll or a particular month.</p></div></section>${movementQuestion()}${dm>=6||current&&answers.crawl==='Yes'?`<section class="calm-section"><h2>A space for new movement.</h2><p>Look again at what can be reached or pulled. Keep unsafe objects out of reach as movement changes.</p>${contextualQuestion('crawl')}</section>`:''}`;resource='safesleep';why='The precise sleep recommendations, including what changes when rolling begins.';source=RESOURCE.safesleep.url;call='For a possible injury or exposure, seek appropriate medical help rather than waiting for app guidance.';}
else {tone='#f0efe1';title=dm<3?'A day shaped<br>by their cues.':dm<6?'Little moments.<br>A familiar rhythm.':dm<9?'Making room<br>for meals and play.':'Everyday things.<br>Shared together.';intro='A flexible picture of the day, not a timetable to keep up with.';const bits=dm<3?[['feed','Feeds','Notice hunger and fullness cues.'],['dev','Connection','A voice, a cuddle or a small awake moment.'],['sleep','Rest','Follow cues and keep sleep safe.']]:dm<6?[['feed','Milk feeds','Keep feeding cues part of the day.'],['dev','Floor play','Supervised space to move and explore.'],['rhythm','A book or song','A small familiar moment, not an activity list.'],['sleep','Rest','Make room for your baby’s needs.']]:[['feed','Milk and meals','If foods have started, include supervised meals.'],['dev','Play','Safe space to handle, reach and explore.'],['rhythm','Shared moments','Name pictures, sing or repeat a favorite game.'],['sleep','Rest','Keep familiar cues flexible.']];body=`<section class="calm-section"><h2>Things that can fit together.</h2><div class="dayflow">${bits.map(([i,t,d])=>`<div class="skill-card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><details class="deepquestion"><summary>Do I need to finish a book or activity?<span>＋</span></summary><p>No. Follow their attention, turn a page when they want to, and stop when they need a break.</p></details>`;resource='play';why='Age-relevant play and movement ideas for ordinary days.';source=RESOURCE.play.url;call='Bring concerns about sleep, feeding or wellbeing to your pediatrician.';}
return `<div class="deeptop">${backButton()}<button class="savequiet" onclick="saveTopic('${t}')">${icon('saved')}${saved.includes('topic:'+t)?'Saved':'Save'}</button></div><header class="deepheader" style="--deepbg:${tone}"><div class="deepicon">${icon(TOPICS.find(x=>x[0]===t)[1])}${t} · ${monthLabel(month)}</div><h1>${title}</h1><p>${intro}</p></header>${!current?'<p class="monthpreview-note">You’re browsing '+monthLabel(month)+'. Check-ins apply to your current month.</p>':''}${body}<section class="calm-resource"><div class="eyebrow">A useful place to turn</div>${handyResource(resource,why)}</section><section class="calm-call"><h3>When to ask your pediatrician</h3><p>${call}</p></section><div class="calm-footer"><a href="${source}" target="_blank" rel="noopener">Source behind this guidance ↗</a></div>`;}
function profileRework(){return backButton()+`<div class="eyebrow">Baby’s details</div><h1>${name()}’s<br>profile.</h1><div class="timelinecard"><h3>${monthLabel(birthdayAge())} from birthday</h3><p>${profile.feed} · ${babyPronounLabel()}${profile.early?' · Born early':''}${profile.example?' · Example baby':''}</p></div><button class="row" onclick="editingProfile=true;draft={...profile};setupStep=1;openPage('setup')">Edit baby’s details ${icon('arrow')}</button>${profile.early?'<button class="row" onclick="openPage(&quot;age-context&quot;)">Understand adjusted age '+icon('arrow')+'</button>':''}<section class="section"><h2>What you’ve shared</h2>${[['Movement',hasMovementAnswer()?safetyAbilityLabel():null],['Food experience',hasFoodAnswer()?foodStageLabel():null],['Sleep training',({...SLEEP_TRAINING_STAGES,tried:'Previously tried'})[answers.sleepTraining]],['Sleep',answers.sleepChange||answers.sleepNeed]].filter(x=>x[1]).map(([t,a])=>`<div class="profile-answer"><span>${t}</span><span>${esc(a)}</span></div>`).join('')||'<p class="hint">No updates yet. Your baby’s age already shapes the guidance.</p>'}<button class="textlink" onclick="openPage('personalize')">Edit check-ins →</button></section><button class="row" onclick="openPage('trust')">How sources are chosen ${icon('arrow')}</button><button class="row" onclick="openPage('welcome')">About Ahead & setup ${icon('arrow')}</button><p class="exp-footer">Your answers, notes and saved moments stay in this browser on this device.</p>`}
function resourceRework(id){const r=RESOURCE[id];return backButton()+`<div class="eyebrow">Where to turn</div><h1 style="margin-top:12px">${r.title}</h1><p class="resource-intro">${r.use}</p><div class="resource-fast"><p>${r.when}</p><div class="cost">${r.cost}</div></div><a class="primary" href="${r.url}" target="_blank" rel="noopener" style="display:block;text-align:center;text-decoration:none;margin:0 0 20px">${id==='solids'?'Open the food database':id==='cdc'?'See milestone examples':id==='cara'?'Explore sleep classes':'Open the guidance'} ↗</a><p class="hint">${r.commercial?'Optional commercial resource.':'Established pediatric or public health publisher'}</p><div class="source-disclosures"><details><summary>Who’s behind it?</summary><p>${r.who}</p></details><details><summary>Why it’s included</summary><p>${r.evidence}</p></details><details><summary>What to keep in mind</summary><p>${r.limits}</p></details><details><summary>Source checks</summary>${r.refs.map(([t,u])=>`<p><a href="${u}" target="_blank" rel="noopener">${t} ↗</a></p>`).join('')}<p>Reference links · October 2026. Costs and availability may change. No affiliate links or paid placements.</p></details></div>`}
function previousResourcesRework(){const needs=[['Understand a new skill','cdc'],['Prepare for the next checkup','visits'],...(month>=4?[['Know when to start foods','readiness'],['Prepare a particular food','solids']]:[]),['Make sense of sleep','aap'],['Find a play idea','play']];return `<div class="eyebrow">Help for a specific question</div><h1>Know where<br>to turn.</h1><p class="resource-intro">Start with what you need. We’ll explain which source fits and why.</p>${needs.map(([q,k])=>`<div class="needrow"><h3>${q}</h3><p>${RESOURCE[k].title} · ${RESOURCE[k].cost}</p><button onclick="openPage('resource:${k}')">See this resource →</button></div>`).join('')}<details class="deepquestion"><summary>Want structured sleep support?<span>＋</span></summary><p>A paid course is optional. Compare its approach, costs and limits before deciding.</p><button class="textlink" onclick="openPage('resource:cara')">Explore Taking Cara Babies →</button></details><section class="section"><h2>Find a topic</h2><input class="search" id="search" placeholder="Try rolling, sleep or solids" aria-label="Search topics" oninput="searchGuides(this.value)"><div id="results">${topicGrid()}</div></section>`}
function aheadRework(){const next=Math.min(12,month+1),story=developmentBrief(developmentMonth(next));let prep=next===4?'New movement can arrive before you expect it. Know the sleep-safety change before rolling starts.':next>=5&&next<=6?'Get familiar with readiness signs and where to look up food preparation. Discuss individual timing with your pediatrician.':next>=7&&next<=10?'Look at your baby’s play space from their level before a new movement makes more things reachable.':next>=11?'Keep your questions for the first-birthday visit close: feeding, development and upcoming transitions.':'Keep your care team’s details close and bring everyday feeding or development questions to the next visit.';const topic=next===4?'Safety':next>=5&&next<=6?'Feeding':next>=7&&next<=10?'Safety':'Health';return backButton()+`<div class="eyebrow">Looking ahead · ${monthLabel(next)}</div><h1 style="margin-top:12px">A little familiarity<br>for what’s next.</h1><div class="skill-card"><h3>${story.title.replace('<br>',' ')}</h3><p>${story.body}</p></div><section class="calm-section" style="margin-top:25px"><h2>Useful beforehand.</h2><p>${prep}</p></section><button class="focus" onclick="month=${next};openPage('topic:${topic}')"><div class="line"><h3>${topic} for the next stage</h3>${icon('arrow')}</div></button><button class="secondary" onclick="month=${next};navigate('home');window.scrollTo(0,0)">Preview ${monthLabel(next).toLowerCase()}</button><p class="hint">Your baby’s timing may differ; check-ins tailor the current month.</p>`}
GUIDES.rolling.title='Rolling from tummy to back';GUIDES.rolling.why='Rolling from tummy to back means turning from lying on the tummy onto the back. It is one direction, not the same as rolling both ways.';GUIDES.rolling.signs=['Look for the direction of the movement you’ve noticed.','The CDC lists tummy-to-back rolling as a skill most babies do by six months.'];GUIDES.rolling.helps=['Offer supervised floor time and safe objects to reach for.','Stop swaddling at signs of trying to roll, before a completed roll.'];GUIDES.rolling.url='https://www.cdc.gov/act-early/milestones/6-months.html';
GUIDES.teeth.helps=['Try a clean-finger gum massage or a suitable solid teething toy for comfort.','When a tooth appears, begin tooth care and arrange the first dental visit.'];GUIDES.safety.helps=['Revisit the spaces your baby can reach as movement changes.','Keep unsafe objects out of reach and review a pediatric home-safety guide.'];
function guideRework(k){const g=GUIDES[k];return backButton()+`<header class="detailhead"><div class="eyebrow">${g.topic}</div><h1>${g.title}</h1></header><p class="guide-answer">${g.why}</p>${k==='rolling'?'<span class="reference-label">CDC reference: by 6 months</span>':''}<section class="calm-section"><h2>What’s happening now</h2>${g.signs.map(x=>`<div class="calm-fact"><p>${x}</p></div>`).join('')}</section><section class="calm-section"><h2>What helps</h2>${g.helps.map(x=>`<div class="calm-fact"><p>${x}</p></div>`).join('')}</section>${guideCheckin(k)}${guideResources(k)}<section class="calm-call"><h3>When to ask your pediatrician</h3><p>${g.call}</p></section><div class="calm-footer"><a href="${g.url}" target="_blank" rel="noopener">${g.source} ↗</a><p>Prototype</p></div>`}

function originalStageSnapshot(t){const x=updatedSnapshot(t),m=month,dm=developmentMonth(),current=isCurrent();
if(t==='Development'){const r=milestoneReference();x.title=developmentMonthlyLabel(dm);x.body=developmentHomeSummary(dm);}
if(t==='Feeding'){const stage=month===5?(isCurrent()&&answers.solids==='Yes'?'new':'preparing'):feedingGuideStage();x.title=FEEDING_GUIDE_TITLES[stage];x.body={milk:'Hunger, fullness, changing milk patterns and spit-ups.',preparing:'Readiness, feeding approaches and setup before the first bite.',new:'Small tastes, iron-rich foods, allergens and feeding cues.',established:month>=11?'Prepare milk and cup transitions alongside familiar meals.':'Textures, self-feeding, cups and fitting meals around milk.'}[stage];if(needsLaterFeedingPlan()){x.title='Make a first-food plan';x.body='Get individual help with starting foods, progression and milk needs.';}}
if(t==='Sleep'){x.title=m<=2?'Day & night developing':m===3?'A rhythm & what’s next':m===4?'4-month sleep regression':m===5?'Nights, naps & settling':m<=8?'Naps & new skills':m<12?'Two naps & bigger feelings':'When one nap comes next';x.body=m>=4&&savedSleepTrainingState()!=='not_started'?'Nights, naps and what to check if sleep changes again.':m<=2?'Why sleep is in short stretches, and what changes next.':m<=4?'Bedtime, naps and the 4-month sleep regression.':m===5?'A picture of the day, practical settling help and optional sleep-training approaches.':m<=8?'How naps begin coming together, with no set transition date.':m<12?'Nap patterns, separation anxiety and what may change next.':'The two-to-one nap transition often comes between 12 and 18 months.';}
if(t==='Health'){const v=visitForMonth();x.title=v.age===0?'The first checkup':v.now?'The '+v.age+'-month visit':'Next visit: '+v.age+' months';x.body=healthNextVisitSummary();}
if(t==='Safety'){const v=safetyValueModel();x.title={setup:'Check your car-seat setup',reaching:'Before the first roll',rolling:'Make room for rolling',moving:'Secure the next spaces',pulling:'Prepare for a higher reach'}[v.stage];x.abilityStage=v.stage;x.body={setup:'Get hands-on help with car-seat installation and fit.',reaching:'Prepare floor play and changing space before the first roll.',rolling:'Clear beyond the mat and consider floor-level diaper changes.',moving:'Review stairs and storage, then prepare furniture as a future handhold.',pulling:'Check anchoring, windows and cords from standing height.'}[v.stage];x.title={setup:'Car-seat fit & installation',reaching:'Space before rolling',rolling:'Floor space & rolling',moving:'Crawling routes & storage',pulling:'Furniture, windows & cords'}[v.stage];const plan=safetyContentPlan();if(!plan.lead.length&&plan.room!=='lead'&&plan.standing!=='lead'){x.title='Your '+({setup:'car-seat',reaching:'floor-play',rolling:'rolling',moving:'crawling',pulling:'standing-height'}[v.stage])+' safety guide';x.body='Revisit the setup and room checklist, or update movement when it changes.';}if(current&&m>=3&&!hasMovementAnswer())x.title='Prepare for new movement';}
if(t==='Daily rhythm'){const first=monthlyPlayActivities(dm,current?currentSafetyMovementStage():null)[0];x.title=playMonthlyTheme(dm);x.body='Try “'+first.title+'”: '+first.why.charAt(0).toLowerCase()+first.why.slice(1);}
return x;}
function categoryPage(t){return completeCategory(t)}function resourcePage(id){return resourceRework(id)}

function factLines(items){return items.map(([t,d])=>`<div class="fact-line"><h3>${t}</h3><p>${d}</p></div>`).join('')}
function insideVisual(html){return html.replace(/^<section class="calm-section"><h2>[^<]*<\/h2>/,'').replace(/<\/section>$/,'')}
function checkinContents(id){if(id==='roll'){const html=movementQuestion();return html.replace(/^<details class="calm-personalize"><summary>[\s\S]*?<\/summary>/,'').replace(/<\/details>$/,'')}return contextualQuestion(id)}
function previousUniformResource(id,reason){const r=RESOURCE[id];return `<button class="resource-card" onclick="openPage('resource:${id}')"><div class="grow"><h3>${r.title}</h3><p>${reason}</p><div class="cost">${r.cost}${r.commercial?' · Optional':''}</div></div><span class="arrow">${icon('arrow')}</span></button>`}
function previousTopicData(t){const dm=developmentMonth(),current=isCurrent(),snap=stageSnapshot(t),r=milestoneReference();let d={t,title:snap.title,intro:snap.body,tone:'#edf0df',notice:'',helps:'',check:'',resource:snap.resource,resourceReason:'',faq:[],call:'',source:''};
if(t==='Development'){d.title='Recognize the little changes.';d.intro='Understand what a skill looks like and how its reference age relates to your baby.';d.notice=`<p class="reference-note">${dm<r?'Developing toward':'Reference point: by'} ${r} months${profile.early?' · using adjusted age':''}. “By” is a reference, not the month a skill starts.</p>${skillCards()}`;d.helps=factLines([['Make space to try','Offer supervised floor time and safe things to reach for.'],['Join the back-and-forth','Respond to sounds, name what catches their attention and pause for a reply.']]);d.check='roll';d.resource='cdc';d.resourceReason='See examples when you’re unsure what a skill looks like.';d.source=developmentBrief(dm).src;d.call='Talk with your pediatrician about missed milestones, loss of a skill or concerns. You don’t need to wait for an app update.';d.faq=[['Does “by six months” mean rolling starts then?','No. It means most babies do that skill by that age. Tummy-to-back rolling is one direction; it differs from rolling both ways.']];}
else if(t==='Feeding'){const mode=feedingState(),milk=milkName();d.tone='#f4eddb';d.title=mode==='prep'?'Getting ready for first bites.':mode==='milk'?'Milk feeds and their cues.':'First tastes, growing skills.';d.intro=mode==='prep'?'Solids generally begin around six months, with developmental readiness. Get familiar with the cues before deciding when to start.':mode==='milk'?milk+' is the food for this stage. Cues and growth help you and your care team understand feeds.':milk+' remains important alongside foods. Preparation and feeding skills develop together.';d.notice=mode==='prep'?insideVisual(readinessVisual()):mode==='milk'?factLines([['Looking for a feed','Hands toward the mouth, turning toward a breast or bottle, and lip movements can signal hunger.'],['Showing fullness','Closing the mouth or turning away can signal fullness. Interpret feeding alongside growth.']]):factLines([['Interest and fullness','Opening for food or closing the mouth can help you recognize their response.'],['A new skill','Food texture and preparation should fit your baby’s development.']]);d.helps=mode==='prep'?insideVisual(mealVisual()):mode==='milk'?factLines([['Ask for support','If feeding is painful, difficult or worrying, bring the difficulty and growth observations to your pediatrician.']]):insideVisual(tableVisual());d.check=month>=4?'solids':'';d.resource=mode==='milk'?'care':'solids';d.resourceReason=mode==='milk'?'Pediatric information for everyday feeding questions.':'Look up how to prepare a particular food. The database is free; guided plans are optional.';d.example=['foods','stage'].includes(mode)?'<a class="resource-example" href="https://solidstarts.com/foods/avocado/" target="_blank" rel="noopener">See an avocado preparation example ↗</a>':'';d.source=mode==='milk'?'https://www.cdc.gov/act-early/milestones/2-months.html':RESOURCE.readiness.url;d.call='Ask about readiness uncertainty, persistent feeding difficulty or concerns about growth. Individual feeding advice comes from your care team.';d.faq=mode==='prep'?[['What should I ask the pediatrician?','“Based on my baby’s head control, sitting and feeding skills, are they ready to start?”'],['What if I’m not sure about a sign?','Use the CDC’s examples and share observations with your pediatrician. You don’t need to run your own feeding test.']]:[['What about allergens?','Ask your pediatrician about introducing common allergens. Severe eczema or an egg allergy can change advice for peanut introduction.'],['Purees, finger foods or a mix?','Discuss approaches with your care team. Safe preparation and textures appropriate to development matter whichever approach you choose.']];}
else if(t==='Sleep'){d.tone='#eeebf4';d.title=current&&answers.sleepChange&&answers.sleepChange!=='Just exploring'?'When nights feel different.':month<3?'Little stretches, day and night.':'Making sense of your nights.';d.intro=month<3?'Newborn sleep comes in short stretches. Regular sleep patterns take time.':'Sleep cycles become more regular around four months, but babies’ patterns and needs vary.';d.notice=factLines([['A change, not a diagnosis','Notice whether waking comes with hunger, discomfort or illness. A calendar label alone cannot explain it.']]);d.helps=factLines([['Keep nighttime care gentle','Use soft voices and quiet care during feeds or changes.'],['Respond to the need','Feeding, a dirty diaper or illness may need attention. Discuss concerns with your pediatrician.']]);d.check='sleep';d.resource='aap';d.resourceReason='Pediatric sleep basics and safe-sleep guidance. Structured courses are optional.';d.source=RESOURCE.aap.url;d.call='Contact your pediatrician if changes accompany illness, feeding or growth concerns, or something that worries you.';d.faq=[['Do we need a sleep course?','No course is required by Ahead. If you want a structured approach, compare its method, fit and cost.']];}
else if(t==='Health'){d.tone='#f4e9e2';const v=visitForMonth(),tooth=current&&answers.tooth==='Yes';d.title=tooth?'A first tooth and everyday care.':'Care through this stage.';d.intro='Keep routine care and questions between visits in one place.';d.notice=factLines([[v.age===0?'The first checkup':v.age+'-month well visit',v.now?'This is a routine visit age in the AAP schedule. Your pediatrician may tailor the schedule.':'The next routine visit in the AAP schedule is around this age. Your pediatrician may tailor timing.'],...(month>=3||tooth?[[tooth?'A tooth has arrived':'Teething questions',tooth?'Tooth care becomes useful as soon as a tooth appears.':'Drooling and chewing can accompany teething. They don’t explain every symptom.']]:[])]);d.helps=factLines([['Bring your observations','Growth, feeding, development, sleep and vaccines are all appropriate questions.'],...(tooth?[[ 'Begin tooth care','Brush twice daily with a rice-grain-sized smear of fluoride toothpaste. Arrange the first dental visit when a tooth appears, no later than the first birthday.']]:[])]);d.check=month>=3?'tooth':'';d.resource=tooth?'toothcare':'visits';d.resourceReason=tooth?'First-tooth brushing, fluoride questions and planning a dental visit.':'Understand routine visits and the questions to bring.';d.source=RESOURCE[d.resource].url;d.call='Don’t attribute fever or unusual symptoms to teething. Contact your pediatrician about symptoms that concern you and follow their urgent-care instructions.';d.faq=[['Where can I check teething signs?','The AAP explains signs, comfort options and remedies to avoid.']];}
else if(t==='Safety'){d.tone='#e8eee1';d.title='Before new movement arrives.';d.intro='Safety preparation stays visible before a milestone and after it happens.';d.notice=factLines([['Trying to roll','Trying comes before a completed roll. A check-in answer or calendar month should not delay the safety change.'],...(dm>=6||current&&answers.crawl==='Yes'?[['A bigger reach','New movement changes what can be reached or pulled.']]:[])]);d.helps=factLines([['Stop swaddling at signs of trying to roll','Don’t wait for a completed roll.'],['Keep sleep firm, flat and clear','Place baby on their back with no soft objects or loose bedding.'],...(dm>=6||current&&answers.crawl==='Yes'?[['Look from floor level','Keep unsafe objects out of reach as movement changes.']]:[])]);d.check=dm>=6?'crawl':'roll';d.resource='safesleep';d.resourceReason='Precise sleep guidance and what changes around rolling.';d.source=RESOURCE.safesleep.url;d.call='For a possible injury or exposure, seek appropriate medical help rather than waiting for app guidance.';d.faq=[['Does a “not yet” answer remove safety guidance?','No. Preparation and anticipatory safety guidance remain visible.']];}
else {d.tone='#efeee0';d.title=dm<3?'A day shaped by their cues.':dm<6?'Little moments, a familiar rhythm.':'Making room for meals and play.';d.intro='A flexible picture of the day, not a timetable to keep up with.';d.notice=factLines([['Their attention and need for a break','Watch what interests them and when they turn away or need rest.'],['A changing mix','Feeds, awake moments and rest can fit together differently as skills change.']]);const bits=dm<3?[['feed','Feeds','Notice hunger and fullness cues.'],['dev','Connection','A voice or a cuddle in an awake moment.'],['sleep','Rest','Follow cues and keep sleep safe.']]:[['feed',dm<6?'Milk feeds':'Milk and meals',dm<6?'Keep feeding cues part of the day.':'If foods have started, include supervised meals.'],['dev','Play','Safe, supervised space to move.'],['rhythm','Shared moments','Name pictures or repeat a favorite song.'],['sleep','Rest','Keep familiar cues flexible.']];d.helps=`<div class="dayflow">${bits.map(([i,t,p])=>`<div class="skill-card">${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`;d.resource='play';d.resourceReason='Age-relevant play ideas that fit into ordinary days.';d.source=RESOURCE.play.url;d.call='Bring concerns about sleep, feeding or wellbeing to your pediatrician.';d.faq=[['Do we need to finish a book or activity?','No. Follow their interest and stop when they need a break.']];}
return d;}
function standardCheckin(d){if(!isCurrent()||!d.check)return '';let content=d.check==='sleep'?sleepChoices().replace(/^<details class="calm-personalize"><summary>[\s\S]*?<\/summary>/,'').replace(/<\/details>$/,''):checkinContents(d.check);return `<details class="checkin-disclosure"><summary>${d.t==='Feeding'?'Already started solids?':d.t==='Development'||d.t==='Safety'?'Tell us what movement you’ve noticed':d.t==='Health'?'Has a first tooth arrived?':'Has sleep changed?'} <span>＋</span></summary><div class="checkin-body">${content}</div></details>`}
function standardTopicPage(t){const d=topicData(t);return `<div class="standard-topic" data-topic-page="${t}"><div class="deeptop">${backButton()}<button class="savequiet" onclick="saveTopic('${t}')">${icon('saved')}${saved.includes('topic:'+t)?'Saved':'Save'}</button></div><header class="topic-header" style="--topic-tone:${d.tone}"><div class="topic-label">${icon(TOPICS.find(x=>x[0]===t)[1])}${t} · ${topicAge(t)}</div><h1>${d.title}</h1>${d.intro?`<p>${d.intro}</p>`:''}</header>${!isCurrent()?'<p class="monthpreview-note">Stage preview. Check-ins apply to the current month.</p>':''}<section class="topic-section" data-section="notice"><h2>What’s happening now</h2>${d.notice}</section><section class="topic-section" data-section="help"><h2>What helps</h2>${d.helps}</section>${standardCheckin(d)}<section class="topic-resource" data-section="resource"><h2 class="resource-heading">A useful place to turn</h2>${uniformResource(d.resource,d.resourceReason)}${d.example||''}</section>${d.faq.length?`<section class="faq-section" data-section="questions"><h2>Questions you might have</h2>${d.faq.map(([q,a])=>`<details class="faq-item"><summary>${q}<span>＋</span></summary><p>${a}</p>${t==='Feeding'&&q==='What should I ask the pediatrician?'?'<button onclick="copyFeedingQuestion(this)">Copy question</button><div id="questionCopy" role="status" class="questioncopy"></div>':''}${t==='Sleep'?'<button onclick="openPage(&quot;resource:cara&quot;)">Explore optional sleep support →</button>':''}${t==='Health'?'<button onclick="openPage(&quot;resource:teething&quot;)">See AAP teething guidance →</button>':''}</details>`).join('')}</section>`:''}<section class="topic-care" data-section="care"><h2>When to ask your pediatrician</h2><p>${d.call}</p></section><div class="topic-source"><a href="${d.source}" target="_blank" rel="noopener">Source behind this guidance ↗</a></div></div>`}


function topicAge(t){return profile.early&&['Development','Daily rhythm','Safety'].includes(t)?monthLabel(developmentMonth())+' adjusted':monthLabel(month)}
function topicData(t){const d=previousTopicData(t),dm=developmentMonth(),r=milestoneReference(),current=isCurrent();
if(t==='Development'){const stage={2:{title:'Getting to know your face and voice.',a:['Looking at you','You may notice your baby watching you move or responding to your face.'],b:['First responses','Smiles and sounds are early ways to connect.']},4:{title:'More sounds, steadier movements.',a:['Sounds back to you','You may hear coos and sounds in response to your voice.'],b:['Holding their head steady','This means keeping the head steady while being held.']},6:{title:'Learning to roll and sit.',a:['Rolling from tummy to back','Turning from lying on their tummy onto their back. Rolling the other way is a different movement.'],b:['Sitting with hands for balance','Leaning on their hands while sitting. This is different from sitting without support.']},9:{title:'Sitting, babbling and exploring.',a:['Sitting without support','Sitting without needing support and getting into sitting.'],b:['New sounds and hand skills','Repeated babbles and moving an object from one hand to the other.']},12:{title:'Gestures, words and new movement.',a:['A wave or a familiar name','Gestures and names for familiar people become part of communication.'],b:['Pulling up and moving along furniture','Standing up by holding on, then taking steps with furniture for support.']}}[r];d.title=stage.title;d.intro=`These skills often develop around this part of the first year. The CDC lists them among things most babies do by ${r===12?'their first birthday':r+' months'}.`;d.notice=factLines([stage.a,stage.b]);d.helps=factLines([[dm<=4?'Pause for their reply':'Give them space to try',dm<=4?'Copy a sound, then pause. Notice how they respond.':'Offer supervised floor time and safe toys to reach for. Let them try without doing every movement for them.'],['Use what you notice','If a movement is hard to describe, the CDC’s examples can help you show your pediatrician what you mean.']]);d.resourceReason='Photos and videos show what the skills look like. Opens the page for this stage.';d.faq=[[r===6?'What if my baby hasn’t rolled yet?':'What if I haven’t seen one of these skills?',dm<r?'Your baby may be working toward it. If you’re unsure or worried, talk with your pediatrician; you don’t have to wait.':'Talk with your pediatrician about a skill not yet seen, any loss of a skill, or other concerns. The checklist isn’t a diagnosis.']];d.call='Talk with your pediatrician if a listed skill is missing by its reference age, a skill has been lost, or you’re concerned. Mention early birth when discussing timing.';}
else if(t==='Feeding'){const mode=feedingState();d.title=mode==='prep'?'Getting ready for solids.':mode==='milk'?'Understanding milk feeds.':'Starting to eat food.';d.intro=mode==='prep'?'Solids generally begin around six months. Knowing the readiness signs now helps you talk through the timing with your pediatrician.':mode==='milk'?milkName()+' is the food for this stage. You can learn a lot from hunger and fullness cues.':milkName()+' still matters as your baby learns to eat food. You don’t have to memorize every food’s preparation.';d.resourceReason=mode==='milk'?'Pediatric answers to everyday feeding questions.':'Look up one food when you need it: preparation examples, textures and age-related guidance.';if(mode==='prep')d.helps=insideVisual(mealVisual())+'<p class="next-step">For now: get familiar with a supported place for meals and bring your readiness questions to the pediatrician.</p>';d.faq=mode==='milk'?[['What if feeding is painful or difficult?','Ask your pediatrician for feeding support. Share what happens during feeds and any growth concerns.']]:d.faq;}
else if(t==='Sleep'){const change=current?answers.sleepChange:null;d.title=change==='More night waking'?'Waking more at night?':change==='Shorter naps'?'Naps have become shorter?':change==='Harder settling'?'Taking longer to settle?':month<3?'Sleep comes in short stretches.':'Understanding changes in sleep.';d.intro=month<3?'Newborn sleep is spread across day and night. Short stretches are part of this early stage.':'Sleep patterns change as babies grow. More waking or shorter naps don’t, on their own, tell you why it’s happening.';d.notice=factLines([[change&&change!=='Just exploring'?change:'Different nights or naps','Notice what has changed from your baby’s usual pattern, rather than comparing with someone else’s baby.'],['Look at the whole day','Has feeding changed? Do they seem uncomfortable or unwell? Share those observations if you ask for help.']]);d.helps=factLines([['Start with their immediate needs','Attend to hunger, a dirty diaper or illness as needed.'],['Make nighttime care quiet','Use soft voices and gentle care during feeds or changes. You don’t need to choose a sleep-training method to do this.']]);d.resourceReason='Start with the free AAP explanation of baby sleep and nighttime care.';d.faq=[['What if I want a more structured plan?','A course can be an optional form of support. Compare the method and costs, and discuss feeding, growth or medical concerns with your pediatrician.']];}
else if(t==='Health'){const v=visitForMonth(),tooth=current&&answers.tooth==='Yes';d.title=tooth?'A first tooth—and your next checkup.':v.age===0?'Your baby’s first checkup.':'Your '+v.age+'-month checkup.';d.intro=v.now?'A routine checkup is a chance to review growth, feeding and development, and ask about vaccines.':'The next routine checkup in the AAP schedule is around '+v.age+' months. Keep questions here as they come up.';d.notice=factLines([[v.now?'A routine visit around now':'The next visit',v.now?'If the visit hasn’t happened yet, check your baby’s appointment plan. Your pediatrician may tailor the timing.':'Your pediatrician may tailor the timing. You can ask questions sooner if something concerns you.'],...(month>=3||tooth?[[tooth?'The first tooth is here':'Drool or chewing',tooth?'Tooth care begins as soon as the first tooth appears.':'These can accompany teething, but don’t explain every symptom. Don’t attribute a fever to teeth.']]:[])]);d.helps=factLines([['Bring a specific observation','For example: “Feeds have become harder this week,” or “I haven’t seen this movement yet.”'],...(tooth?[['Start brushing','Brush twice daily with a rice-grain-sized smear of fluoride toothpaste. Arrange a first dental visit when a tooth appears, no later than the first birthday.']]:[['Keep your questions together','Feeding, sleep, development and vaccines all belong in the conversation.']])]);d.resourceReason=tooth?'First-tooth brushing, fluoride and when to see a dentist.':'See what routine visits are for and when they usually happen.';}
else if(t==='Safety'){const moving=current&&answers.crawl==='Yes';d.title=moving?'A safer space for moving.':'Safe sleep as movement changes.';d.intro=moving?'As your baby can reach more, take another look at the space they explore.':'The sleep setup stays simple. A new attempt to roll adds one important change.';d.notice=factLines([['Signs of trying to roll','You don’t need a completed roll before changing how you swaddle.'],...(moving||dm>=6?[['More things within reach','Moving, reaching or pulling up can make a previously safe space need another look.']]:[])]);d.helps=factLines([['Stop swaddling when trying to roll','Don’t wait for a certain month or a full roll.'],['Keep the sleep space clear','Place your baby on their back on a firm, flat surface with no soft objects or loose bedding.'],...(moving||dm>=6?[['Look from their level','Check what can be reached or pulled and keep unsafe objects out of reach.']]:[])]);d.resourceReason='The AAP’s specific sleep recommendations, including what changes around rolling.';d.faq=[['What if my baby is only trying to roll?','Signs of trying to roll are enough to stop swaddling. A completed roll is not required.']];}
else {d.title=dm<3?'Feeds, small awake moments and rest.':dm<6?'Room for play between feeds and rest.':'Fitting meals, play and rest together.';d.intro='You don’t need to create a perfect day. Use familiar moments and your baby’s cues to give the day some shape.';d.notice=factLines([['Interested in you or a toy','An ordinary awake moment can be a chance to talk, play or look at a book.'],['Ready for a break','Turning away or losing interest is a reason to pause. You don’t have to finish an activity.']]);d.resourceReason='Simple play and movement ideas chosen by age. Pick one that fits your day.';d.faq=[['Do I need to add more activities?','Ordinary talking, reading, singing and supervised play offer chances to connect. Follow their interest rather than completing a list.']];}
return d;}
function resourceTarget(id){return id==='cdc'?developmentBrief(developmentMonth()).src:RESOURCE[id].url}
function uniformResource(id,reason){const r=RESOURCE[id];return `<div class="resource-card"><a class="grow" href="${resourceTarget(id)}" target="_blank" rel="noopener"><h3>${r.title}</h3><p>${reason}</p><div class="cost">${r.cost}${r.commercial?' · Optional commercial resource':''}</div><span class="resource-open">${id==='cdc'?'See the skill examples':id==='solids'?'Open the food lookup':'Open this resource'} ↗</span></a><span class="arrow">${icon('arrow')}</span></div><button class="resource-why" onclick="openPage('resource:${id}')">Why it’s here, costs and limits</button>`}
function resourcesRework(){const items=[['Development','“What does this skill look like?”','cdc','Photos and videos for your baby’s current developmental stage.'],['Sleep','“What can help with sleep?”','aap','Free pediatric guidance to start with; structured courses are optional.'],['Feeding',month>=4?(foodStage()==='preparing'?'“How do I get ready for foods?”':'“How do I prepare this food?”'):'“How do I understand feeds?”',month>=4?(foodStage()==='preparing'?'readiness':'solids'):'care',month>=4?(foodStage()==='preparing'?'Readiness signs to learn before first bites.':'A specific-food lookup when you need preparation help.'):'Pediatric information for common feeding questions.'],['Health','“What should I know before our visit?”','visits','Routine checkups and questions you can bring.'],['Safety','“What needs to change at home?”','homeSafety','A room-by-room guide to the spaces baby can reach.'],['Daily rhythm','“How do I bathe and care for my baby?”','care','Baths, skin, nails and everyday baby care.']];return `<div class="eyebrow">All your baby-care sources together</div><h1>A place to turn,<br>when you need it.</h1><p class="resource-intro">Choose a question to find a trusted source.</p>${items.map(([cat,q,k,why])=>`<div class="resource-compact-row"><div class="resource-category">${displayTopic(cat)}</div><h2>${q}</h2><p>${RESOURCE[k].title} · ${why}</p><p class="hint">${RESOURCE[k].cost}</p><div class="row-actions"><a href="${resourceTarget(k)}" target="_blank" rel="noopener">Open resource ↗</a><button onclick="openPage('resource:${k}')">Why this source?</button></div></div>`).join('')}<details class="deepquestion"><summary>Looking for structured sleep support?<span>＋</span></summary><p>Taking Cara Babies is an optional commercial service. Learn about its approach and cost before deciding.</p><button class="textlink" onclick="openPage('resource:cara')">See expertise, approach and costs →</button></details><section class="section"><h2>Find a question</h2><input class="search" placeholder="Try rolling, sleep or solids" aria-label="Search guidance" oninput="searchGuides(this.value)"><div id="results">${topicGrid()}</div></section>`}


const experienceState={};let visitQuestion='';
function expSelect(t,k){experienceState[t+':'+month]=k;render()}
function expAnswer(id,v){setAnswer(id,v)}
function rollAnswer(v){if(v==='Yes'){const old=answers.rollDirection;setMovement(old==='Back to tummy'||old==='Both ways'?'Both ways':'Tummy to back')}else setMovement(v==='Not sure'?'Not sure':'Not yet')}
function sceneSvg(kind){if(['sit','head','open','swallow','milk','food','smile'].includes(kind))return babySvg(kind);if(kind==='roll')return `<svg viewBox="0 0 190 120" fill="none" aria-hidden="true"><ellipse cx="92" cy="101" rx="73" ry="7" fill="#d9e2c5"/><path d="M58 78q28-20 54 1l12 16H51Z" fill="#b8cba1"/><circle cx="42" cy="75" r="18" fill="#ead3b4"/><path d="m37 73 1 .2m9-1 .2 .2" stroke="#78835d" stroke-width="2.5" stroke-linecap="round"/><path d="M72 29c29-20 68-6 71 28m-8-7 8 7 6-9" stroke="#a0b581" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><path d="m86 86 15 12m8-13 14 10" stroke="#95ae7c" stroke-width="6" stroke-linecap="round"/></svg>`;if(kind==='sleep')return `<svg viewBox="0 0 160 130" fill="none" aria-hidden="true"><path d="M102 21a43 43 0 1 0 29 65c-30 9-54-12-29-65Z" fill="#c9bfdd"/><path d="m120 20 3 9 9 3-9 3-3 9-3-9-9-3 9-3Z" fill="#e3cea0"/><circle cx="47" cy="23" r="3" fill="#c1cdaa"/><circle cx="135" cy="89" r="3" fill="#c1cdaa"/><path d="M63 71q4 4 9 0m15 0q4 4 9 0M74 85q5 4 10 0" stroke="#9b8eaf" stroke-width="2" stroke-linecap="round"/></svg>`;if(kind==='tooth')return `<svg viewBox="0 0 140 120" fill="none" aria-hidden="true"><path d="M40 20c-21 7-15 34-10 50s8 35 18 32 8-28 21-28 12 31 22 28 13-28 18-43 7-34-7-40-23 2-32 1-18-5-30 0Z" fill="#fffdf1" stroke="#d6d9c2" stroke-width="1.5"/><path d="M55 46h.2m29 0h.2" stroke="#9eac84" stroke-width="3" stroke-linecap="round"/><path d="M61 60q9 7 18 0" stroke="#b6b995" stroke-width="2" stroke-linecap="round"/><path d="m116 14 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" fill="#d4bf94"/></svg>`;if(kind==='bed')return `<svg class="empty-bed" viewBox="0 0 200 120" fill="none" aria-hidden="true"><path d="M29 28v72m141-72v72M29 35h141M29 89h141" stroke="#b9bc9b" stroke-width="4" stroke-linecap="round"/><path d="M44 35v53m18-53v53m19-53v53m19-53v53m20-53v53m20-53v53m16-53v53" stroke="#ccd0b3" stroke-width="2"/><path d="m32 65 17-15h115l5 15Z" fill="#fffdf1" stroke="#e0e2ca"/><path d="M32 65h136v9H32Z" fill="#dce4ca"/><path d="M29 100v10m141-10v10" stroke="#b9bc9b" stroke-width="4" stroke-linecap="round"/></svg>`;if(kind==='room')return `<svg viewBox="0 0 190 125" fill="none" aria-hidden="true"><path d="M20 108h152M26 108V25h113" stroke="#d5dcc1" stroke-width="2"/><path d="M49 66h64v39H49Z" fill="#d7c69d"/><path d="M49 79h64m-64 13h64" stroke="#bcae89" stroke-width="1.5"/><circle cx="81" cy="73" r="1.5" fill="#a59974"/><circle cx="81" cy="85" r="1.5" fill="#a59974"/><circle cx="81" cy="98" r="1.5" fill="#a59974"/><ellipse cx="147" cy="105" rx="21" ry="4" fill="#dde5cc"/><circle cx="142" cy="96" r="7" fill="#b8cba0"/><path d="M121 31h28v31h-28Z" fill="#f2e9cc"/><path d="M134 62v31" stroke="#bfc7a6" stroke-width="2"/></svg>`;if(kind==='book')return `<svg viewBox="0 0 170 120" fill="none" aria-hidden="true"><path d="M85 30C63 17 41 20 24 29v66c22-10 41-7 61 6 19-13 41-16 62-6V29c-21-10-42-10-62 1Z" fill="#c3d1aa"/><path d="M85 35C65 25 46 27 31 34v51c20-6 35-3 54 8 17-11 37-13 55-8V34c-20-7-36-8-55 1Z" fill="#fffbed"/><path d="M85 35v58" stroke="#d7dec5"/><circle cx="56" cy="53" r="11" fill="#e1c68b"/><path d="m104 70 8-21 14 21Z" fill="#bdcda4"/></svg>`;return icon('dev')}
function briefItem(k,label,title,text,visual,action,source,care){return {k,label,title,text,visual,action,source,care}}
function experienceItems(t){const dm=developmentMonth(),ref=milestoneReference(),current=isCurrent(),r=RESOURCE;let items=[],tone='#edf0df';
if(t==='Development'){if(ref===6)items=[briefItem('roll','Rolling','Turning from tummy to back.','This means turning from lying on their tummy onto their back. Rolling back to tummy is a different movement.','roll',['Give them room to try.','Offer supervised floor time and safe toys to reach toward. Follow their interest rather than practicing to a deadline.'],'cdc','If your baby hasn’t shown a listed skill by its reference age, has lost a skill or you’re worried, talk with your pediatrician.'),briefItem('sit','Sitting','Balancing with their hands.','At this stage, sitting can mean leaning on the hands for balance. It is not the same as sitting without support.','sit',['Stay close during play.','Supervise sitting practice and follow your baby’s cues.'],'cdc','Discuss missing skills, lost skills or concerns with your pediatrician.'),briefItem('sounds','Sounds','A little back-and-forth.','Sounds can become a conversation: your baby makes one, you respond, and they try again.','smile',['Pause for a reply.','Copy one sound and leave a little space. You don’t need a special activity.'],'cdc','Discuss developmental concerns or any loss of skills with your pediatrician.')];else if(ref<=4)items=[briefItem('connect','Connection',ref===2?'Your face and voice matter.':'More ways to respond.',ref===2?'Looking at your face, watching you move and responding to your voice are early ways to connect.':'Cooing and sounds back to you are ways your baby joins an exchange.','smile',['Leave a little pause.','Talk or copy a sound, then notice your baby’s response. Take a break when they turn away.'],'cdc','Talk with your pediatrician about missed milestones, lost skills or concerns.'),briefItem('movement','Movement',ref===2?'Small movements, new control.':'A steadier head.',ref===2?'The two-month milestones include lifting the head during tummy time and moving arms and legs.':'Holding the head steady while being held is a four-month milestone.','head',['Keep play supervised.','Offer safe awake play and follow your baby’s cues.'],'cdc','Bring movement concerns or any loss of skills to your pediatrician.')];else items=[briefItem('move','Movement',ref===9?'Sitting without support.':'Pulling up to stand.',ref===9?'This includes sitting without needing support and getting into a sitting position.':'Holding on to stand and moving along furniture opens up a new view.','sit',['Make room to explore.','Give your baby a safe, supervised space to move.'],'cdc','Discuss missing skills, lost skills or concerns with your pediatrician.'),briefItem('communicate','Communication',ref===9?'Babbles are taking shape.':'Gestures have meaning.',ref===9?'Repeated sounds and lifting arms to be picked up are ways to communicate.':'A wave or a familiar name can carry a message between you.','smile',['Join the exchange.','Name what catches their interest and respond to gestures or sounds.'],'cdc','Share concerns about communication or lost skills with your pediatrician.')];}
else if(t==='Feeding'){tone='#f4eddb';const f=feedingState();if(f==='prep')items=[briefItem('ready','Readiness','More than watching your plate.','Solids generally begin around six months. Head control, supported sitting, opening for food and moving food back to swallow help inform the conversation.','readiness',['One useful next step.','Ask: “Based on my baby’s head control, sitting and feeding skills, are they ready to start?”'],'readiness','Ask your pediatrician about readiness uncertainty, feeding difficulty or growth concerns.'),briefItem('setup','A place to eat','Supported, supervised meals.','Get familiar with an upright, supported place for meals and follow the seat’s safety instructions.','sit',['Keep it small.','You can prepare a place for meals without choosing every food or buying a course.'],'readiness','Discuss individual timing with your pediatrician, especially after early birth.'),briefItem('lookup','Food help','A question you can look up.','When a specific food comes along, a food database can show preparation examples. You don’t need to memorize them in advance.','food',['Try an example.','Look at how one food is prepared. Use guidance suited to your baby’s skills and ask about individual needs.'],'solids','Bring feeding difficulty or readiness concerns to your pediatrician.')];else if(f==='milk')items=[briefItem('cues','Their cues','Learning hunger and fullness.', 'Turning toward a feed or bringing hands toward the mouth can signal hunger. Closing the mouth or turning away can signal fullness.','milk',['Follow what you notice.','Share feeding and growth observations with your care team if you’re unsure.'],'care','Ask for support if feeding is painful, difficult or worrying.')];else items=[briefItem('meals','Milk + food','Milk stays in the picture.',milkName()+' remains important alongside food. New tastes and textures are also new skills.','milk',['Watch their response.','Opening for food or closing the mouth can help you notice hunger and fullness.'],'readiness','Ask about persistent feeding difficulty or growth concerns.'),briefItem('serve','Serving food','“How do I serve this?”','Food texture and preparation should fit your baby’s development. A food-specific lookup can help with that exact question.','food',['Look up one food.','Start with a preparation example, such as avocado. Always supervise eating.'],'solids','Bring concerns about swallowing, feeding or individual preparation needs to your pediatrician.'),briefItem('cues','Their cues','Interest, pauses and enough.','Your baby’s response helps you recognize interest or fullness. Learning to eat involves new skills, not just amounts.','smile',['Make room for pauses.','Notice opening for food, closing the mouth or turning away. Ask your care team about ongoing difficulties.'],'readiness','Discuss persistent feeding difficulty or growth concerns.')];}
else if(t==='Sleep'){tone='#eeebf4';items=[briefItem('waking','More waking','Nights have changed.','More waking can happen as sleep develops, but it doesn’t identify the cause. Consider feeding needs, discomfort and illness too.','sleep',['Start with their needs.','Attend to hunger, a dirty diaper or illness as needed. Keep nighttime care quiet and gentle.'],'aap','Contact your pediatrician if changes accompany illness, feeding or growth concerns, or something worries you.'),briefItem('naps','Shorter naps','A different nap pattern.','Sleep patterns and needs vary between babies. A shorter nap alone doesn’t tell you what caused the change.','sleep',['Look at the whole picture.','Notice feeds, comfort and signs of illness alongside the change. Share these observations if you need help.'],'aap','Ask your pediatrician about a sleep change with feeding, growth or illness concerns.'),briefItem('settle','Settling','Taking longer to settle.','First consider comfort and immediate needs. You don’t have to choose a sleep-training method to respond to your baby.','sleep',['Keep a familiar, quiet moment.','Use soft voices and gentle care. If you want structured support, compare the approach and costs before choosing it.'],'aap','Discuss persistent concerns, illness or feeding difficulties with your pediatrician.')];}
else if(t==='Health'){tone='#f4e9e2';const v=visitForMonth(),has=current&&answers.tooth==='Yes';items=[briefItem('visit','Checkup',v.age===0?'The first checkup.':'The '+v.age+'-month checkup.',v.now?'This is a routine visit age in the AAP schedule. Growth, feeding, development and vaccines belong in the conversation.':'The next routine visit in the AAP schedule is around '+v.age+' months. Your pediatrician may tailor the timing.','calendar',['Bring one question.','Choose what’s on your mind and we’ll help you phrase it.'],'visits','Ask sooner if you’re concerned; you don’t need to wait for a routine visit.'),briefItem('tooth','Teeth',has?'A tooth is here.':'Could this be teething?',has?'Tooth care begins with the first tooth. Brush twice daily with a rice-grain-sized smear of fluoride toothpaste.':'Drool and chewing can accompany teething, but they don’t explain every symptom. Don’t attribute a fever to teeth.','tooth',[has?'Begin a small routine.':'A comfort option.',has?'Arrange a first dental visit when a tooth appears, no later than the first birthday.':'A clean-finger gum massage or a suitable solid teething toy can offer comfort.'],has?'toothcare':'teething','Ask your pediatrician about fever or unusual symptoms rather than assuming teeth are the cause.')];}
else if(t==='Safety'){tone='#e8eee1';items=[briefItem('sleep','Sleep space','Firm, flat and clear.','Place your baby on their back on a firm, flat sleep surface with no soft objects or loose bedding.','bed',['Trying to roll? Stop swaddling.','The change matters at signs of trying to roll, before a completed roll. Don’t wait for a particular month.'],'safesleep','For a possible injury or exposure, seek appropriate medical help.'),briefItem('room','Their space','Look from their level.','New movement changes what can be reached or pulled. Revisit the space as your baby explores more.','room',['Pick one area to look at.','Start with where your baby plays. Keep unsafe objects out of reach.'],'cdc','For a possible injury or exposure, seek appropriate medical help.')];}
else {tone='#efeee0';items=[briefItem('play','Play','A small moment of play.','Supervised floor time and a safe object give your baby something to explore. Let their interest lead.','smile',['Try this now.','Put a safe toy within reach during supervised awake play. Notice what they do; there’s no task to complete.'],'play','Bring concerns about movement or development to your pediatrician.'),briefItem('book','A book','One picture is enough.','You don’t need to finish the book. Point to a picture that catches their interest and name it.','book',['Follow their lead.','Repeat a sound or turn a page together. Stop when they need a break.'],'play','Bring concerns about development or wellbeing to your pediatrician.'),briefItem('rhythm','The day','A little shape to the day.','Feeding, connection, supervised play and rest can fit together flexibly. It doesn’t need to be a perfect schedule.','milk',['Keep one familiar moment.','A song or book can be a repeatable part of the day. Make room for changing needs.'],'play','Bring concerns about feeding, sleep or wellbeing to your pediatrician.')];}return {items,tone};}
function experienceAnswerBlock(t,item){if(!isCurrent())return '';if(t==='Development'&&item.k==='roll'){const a=answers.rollDirection;return `<div class="inline-response"><h3>Have you seen tummy-to-back rolling?</h3><div class="answers">${['Yes','Not yet','Not sure'].map(v=>`<button class="chip ${v==='Yes'&&['Tummy to back','Both ways'].includes(a)||v==='Not yet'&&a==='Not yet'||v==='Not sure'&&a==='Not sure'?'on':''}" onclick="rollAnswer('${v}')">${v}</button>`).join('')}</div>${a?`<p class="feedback" role="status">${['Tummy to back','Both ways'].includes(a)?'You’ve seen this movement. Keep supervised play and sleep-safety guidance close.':a==='Not sure'?'The visual examples can help you recognize it. Share uncertainty with your pediatrician.':'Give them safe space to try. Talk with your pediatrician if you’re concerned about progress.'}</p>`:''}</div>`}if(t==='Feeding'&&month>=4)return `<details class="movement-picker"><summary>${answers.solids==='Yes'?'Solids have started · Change':'Already started solids? Update guidance ＋'}</summary><div class="answers">${['Yes','Not yet','Not sure'].map(v=>`<button class="chip ${answers.solids===v?'on':''}" onclick="setAnswer('solids','${v}')">${v}</button>`).join('')}</div></details>`;if(t==='Health'&&item.k==='tooth')return `<div class="inline-response"><h3>Has a first tooth arrived?</h3><div class="answers">${['Yes','Not yet','Not sure'].map(v=>`<button class="chip ${answers.tooth===v?'on':''}" onclick="setAnswer('tooth','${v}')">${v}</button>`).join('')}</div></div>`;return '';}
function chooseVisitQuestion(v){visitQuestion=v;const y=window.scrollY;render();window.scrollTo(0,y)}
async function copyVisitQuestion(){try{await navigator.clipboard.writeText(visitQuestion);$('#visitCopyStatus').textContent='Copied for your conversation.'}catch{$('#visitCopyStatus').textContent=visitQuestion}}
function experienceNext(t,item){let content=`<h3>${item.action[0]}</h3><p>${item.action[1]}</p>`;if(t==='Health'&&item.k==='visit')content=`<h3>What’s on your mind?</h3><div class="question-buttons">${[['Feeding','Is feeding and growth on track for my baby?'],['Sleep','How should we think about the sleep change we’re seeing?'],['Development','Are the skills I’m noticing on track for my baby?']].map(([l,q])=>`<button onclick="chooseVisitQuestion('${q}')">${l}</button>`).join('')}</div>${visitQuestion?`<p class="question-result">“${visitQuestion}”</p><button onclick="copyVisitQuestion()">Copy this question</button><p id="visitCopyStatus" class="hint" role="status"></p>`:'<p class="hint" style="margin-top:10px">Choose a topic for a question you can bring.</p>'}`;if(t==='Feeding'&&['serve','lookup'].includes(item.k))content+=`<a class="resource-example" href="https://solidstarts.com/foods/avocado/" target="_blank" rel="noopener">Open an avocado preparation example ↗</a>`;if(t==='Sleep'&&item.k==='settle')content+='<button onclick="openPage(&quot;resource:cara&quot;)">Compare optional structured support →</button>';return `<section class="exp-next"><div class="eyebrow">Something useful for you</div>${content}</section>`}
function categoryExperience(t){const {items,tone}=experienceItems(t),key=t+':'+month;let preferred=experienceState[key];if(!preferred){preferred=t==='Safety'&&developmentMonth()>=7?'room':t==='Health'&&isCurrent()&&answers.tooth==='Yes'?'tooth':items[0].k}const item=items.find(x=>x.k===preferred)||items[0],resource=RESOURCE[item.source],isDev=t==='Development';let visual=item.visual==='calendar'?`<div class="calendar"><span class="month-number">${visitForMonth().age===0?'1st':visitForMonth().age}</span><small>${visitForMonth().age===0?'checkup':'month visit'}</small></div>`:item.visual==='readiness'?`<div class="readiness-mini">${['sit','head','open','swallow'].map(k=>`<button class="${selectedFeedingCue===k?'active':''}" onclick="chooseCue('${k}')" aria-label="${CUES[k][0]}">${babySvg(k)}<span>${CUES[k][0]}</span></button>`).join('')}</div>`:sceneSvg(item.visual);return `<div class="experience" data-topic-page="${t}"><div class="exp-top">${backButton()}<button class="savequiet" onclick="saveTopic('${t}')">${icon('saved')}${saved.includes('topic:'+t)?'Saved':'Save'}</button></div><header class="exp-intro"><h1>${t}</h1><p>${name()} · ${topicAge(t)}${!isCurrent()?' · Looking '+(month>actualMonth()?'ahead':'back'):''}</p></header><nav class="exp-tabs" role="group" aria-label="${t} questions">${items.map(i=>`<button class="exp-tab" aria-pressed="${i.k===item.k}" onclick="expSelect('${t}','${i.k}')">${i.label}</button>`).join('')}</nav><section class="exp-panel" role="region" aria-label="${item.label}" style="--exp-tone:${tone}"><div class="exp-scene">${visual}</div><div class="mini-label">${isCurrent()?'For this stage':'A stage preview'}</div><h2>${item.title}</h2><p class="answer">${item.text}</p>${isDev?`<p class="age-explanation">The CDC lists this among skills most babies do by ${milestoneReference()===12?'the first birthday':milestoneReference()+' months'}. It may start before then.</p>`:''}${item.visual==='readiness'&&selectedFeedingCue?`<p class="age-explanation" role="status">${CUES[selectedFeedingCue][2]}</p>`:''}${experienceAnswerBlock(t,item)}</section>${experienceNext(t,item)}<div class="exp-support">${icon('explore')}<div><a href="${resourceTarget(item.source)}" target="_blank" rel="noopener">${item.source==='cdc'?'See visual examples from the CDC':item.source==='solids'?'Look up a food with Solid Starts':item.source==='play'?'More everyday play ideas from the AAP':'Keep '+resource.title+' handy'} ↗</a><p>${resource.cost}${resource.commercial?' · Optional commercial resource':''}</p><button onclick="openPage('resource:${item.source}')">Why this source?</button></div></div><p class="exp-care"><b>Ask your pediatrician:</b> ${item.care}</p><p class="exp-footer">Prototype</p></div>`}


const DEVELOPMENT_DOMAINS={
2:{Social:['Settles with your voice or touch','Looks at your face','Seems glad to see you','Smiles back at you'],Talking:['Makes sounds beyond crying','Responds to loud sounds'],Thinking:['Watches you move','Looks at a toy for a few seconds'],Movement:['Lifts head during tummy time','Moves both arms and legs','Briefly opens hands']},
4:{Social:['Smiles to get your attention','Chuckles during play','Uses sounds or movement to keep your attention'],Talking:['Coos','Makes sounds back to you','Turns toward your voice'],Thinking:['Opens for breast or bottle when hungry','Studies their hands'],Movement:['Keeps head steady while held','Holds a toy placed in their hand','Swipes at toys','Brings hands to mouth','Pushes onto elbows during tummy time']},
6:{Social:['Knows familiar people','Likes looking at self in a mirror','Laughs'],Talking:['Takes turns making sounds with you','Blows raspberries','Squeals'],Thinking:['Puts things in mouth to explore','Reaches to grab a toy','Closes lips to show they don’t want more food'],Movement:['Rolls tummy to back','Pushes up with straight arms on tummy','Leans on hands when sitting']},
9:{Social:['May be shy or clingy with strangers','Shows different facial expressions','Looks when you call their name','Reacts when you leave','Enjoys peekaboo'],Talking:['Makes repeated babbles','Raises arms to be picked up'],Thinking:['Looks for a dropped object','Bangs objects together'],Movement:['Gets into sitting','Passes objects between hands','Rakes food with fingers','Sits without support']},
12:{Social:['Joins games like pat-a-cake'],Talking:['Waves goodbye','Uses a name for a parent','Pauses or stops at “no”'],Thinking:['Puts an object in a container','Looks for something you hide'],Movement:['Pulls up to stand','Steps while holding furniture','Drinks from an open cup you hold','Picks up small things with thumb and finger']}
};
const SIX_EXPLANATIONS={
'Knows familiar people':'Notice how your baby responds to people they see often.',
'Likes looking at self in a mirror':'Interest in their reflection is something to notice. Use a baby-safe mirror while you supervise.',
'Laughs':'Listen for a laugh during a familiar game or playful interaction.',
'Takes turns making sounds with you':'You make a sound, your baby responds, and the exchange continues. A pause gives them a turn.',
'Blows raspberries':'Sticks the tongue out and blows air, making a playful sound.',
'Squeals':'Makes higher-pitched squealing sounds during awake moments.',
'Puts things in mouth to explore':'Mouthing is a way to explore. Offer safe objects while supervising.',
'Reaches to grab a toy':'Makes a reach toward a toy they want, rather than only holding one placed in their hand.',
'Closes lips to show they don’t want more food':'Closing the mouth can be a fullness cue. Notice their response rather than pushing for more.',
'Rolls tummy to back':'Turns from lying on their tummy onto their back. Rolling from back to tummy is a different movement.',
'Pushes up with straight arms on tummy':'During tummy time, pushes the upper body up with straight arms rather than resting on elbows.',
'Leans on hands when sitting':'Uses hands for balance while sitting. This differs from sitting without support.'
};
function domainExplanation(ref,domain,label){if(ref===6)return SIX_EXPLANATIONS[label];if(domain==='Social')return 'Notice this in ordinary connection and play. You don’t need to turn the moment into a test.';if(domain==='Talking')return 'Notice the sounds or gestures your baby uses. Respond, then pause to give them a turn.';if(domain==='Thinking')return 'Look for this during supervised play or everyday care. Follow what catches their attention.';return 'Notice the movement during safe, supervised awake time. Use the CDC’s examples if you’re unsure what it looks like.';}
function completeDevelopment(){const dm=developmentMonth(),ref=milestoneReference(),domains=DEVELOPMENT_DOMAINS[ref],source=developmentBrief(dm).src;const icons={Social:'health',Talking:'rhythm',Thinking:'spark',Movement:'dev'};return `<div class="development-overview"><div class="exp-top">${backButton()}<button class="savequiet" onclick="saveTopic('Development')">${icon('saved')}${saved.includes('topic:Development')?'Saved':'Save'}</button></div><header class="dev-heading"><div class="tiny-sprig">${icon('dev')}</div><div class="eyebrow">Development · ${name()} · ${topicAge('Development')}</div><h1>The whole picture,<br>in four parts.</h1><p>Skills most babies do by ${ref===12?'their first birthday':ref+' months'}, according to the CDC. They can emerge earlier; this isn’t a test for today.</p></header><div class="overview-subhead"><h2>What you may notice</h2><p>By ${ref===12?'12 months':ref+' months'}</p></div><div class="dev-grid">${Object.entries(domains).map(([domain,observations])=>`<section class="dev-domain ${domain.toLowerCase()}" data-domain="${domain}"><header><span class="domain-icon">${icon(icons[domain])}</span><h2>${domain==='Talking'?'Communication':domain}</h2></header><div class="domain-observations">${observations.map(label=>`${journeySkillRow(label)}`).join('')}</div></section>`).join('')}</div>${profile.early?'<p class="dev-reference">Development follows adjusted age.</p>':''}${commonQuestions('Development')}${preparationPanel('Development')}<section class="guide-footer development-footer"><a class="guide-resource-row development-examples" href="${source}" target="_blank" rel="noopener"><span class="guide-resource-mark" aria-hidden="true">${icon('dev')}</span><span><b>See the skill examples</b><small>CDC milestone photos & videos</small></span><span aria-hidden="true">↗</span></a><details class="sources-disclosure"><summary>Development resources &amp; sources <span aria-hidden="true">＋</span></summary><div class="dev-footer"><p>Milestone examples come from the CDC’s Learn the Signs. Act Early. program.</p><button onclick="openPage('resource:cdc')">About the CDC guidance</button></div></details></section><p class="exp-footer">Prototype</p></div>`;}


const observation=(text,detail)=>({text,detail});const group=(label,ic,items)=>({label,ic,items});
function nextVisitAge(){return [...WELL_VISITS,15].find(n=>n>month)??15}
function upcomingFor(t){const started=isCurrent()&&answers.solids==='Yes',tooth=isCurrent()&&answers.tooth==='Yes',moving=isCurrent()&&answers.crawl==='Yes';
if(t==='Feeding'&&!started&&month>=3&&month<=8)return {when:month<=5?'Around 6 months · when ready':'Before foods begin · individual timing',title:'First foods can feel familiar before the first bite.',intro:month<=4?'You have time to learn. Start with the readiness signs and a reliable place to check food preparation.':'A little preparation can make the transition easier. Starting depends on readiness, not a date to keep up with.',items:month<=4?[observation('Learn what readiness looks like','Head control, supported sitting and moving food back to swallow are part of the picture. Bring uncertainty to your pediatrician.'),observation('Know where to look up a food','Solid Starts has food-specific preparation examples. Its free database can be used without following a paid plan.'),observation('Bring timing to a routine visit','Ask how your baby’s skills and individual needs affect when to start. Mention early birth or feeding concerns.')]:[observation('Get familiar with the meal setup','Think about a supported, upright place for meals and staying close to supervise. Follow the seat’s instructions.'),observation('Learn choking prevention and response','Use appropriate infant first-aid education. Ask your care team where to learn; an app summary is not training.'),observation('Ask about allergens and first foods','Bring questions about introducing allergens, especially with severe eczema or an egg allergy.')],resource:'readiness',resourceText:'See readiness signs and examples',foot:'Learning and preparing do not mean you should start now. Your pediatrician can help with individual readiness.'};
if(t==='Feeding'&&month>=9&&month<=11)return {when:'Looking toward the first birthday',title:'Get familiar with the next feeding transition.',intro:'You can bring milk, cups and family-meal questions to the first-birthday visit before making changes.',items:[observation('Keep your milk questions together','Ask your pediatrician what changes are appropriate for your baby at the first birthday.'),observation('Learn about cups alongside meals','Discuss how cup skills and your baby’s feeding needs fit the transition.')],resource:'care',resourceText:'AAP baby-care guidance',foot:'A conversation to prepare for, not a deadline to change every feed.'};
if(t==='Feeding')return {when:'As food skills grow',title:'Know how preparation changes with new skills.',intro:'You can look up the next texture or food when it becomes relevant, without memorizing a whole feeding plan.',items:[observation('Keep a preparation reference close','Use examples suited to your baby’s development when serving a new food.'),observation('Bring individual nutrition questions','Ask your pediatrician about variety, allergens and your baby’s feeding needs.')],resource:'solids',resourceText:'Keep the food database handy',foot:'Use your baby’s skills and care team’s advice rather than a fixed date for every change.'};
if(t==='Safety'||t==='Development')return {when:moving?'As reach and movement keep changing':'Before new movement expands their reach',title:'Prepare the space before they get there.',intro:'Rolling, scooting and pulling can change what’s reachable. Safety preparation doesn’t need to wait for a completed milestone.',items:[observation('Look from the floor','Review what can be reached, pulled or put in the mouth. Start with the space where your baby plays.'),observation('Keep sleep guidance close','Stop swaddling at signs of trying to roll. Continue placing baby on their back on a firm, flat, clear sleep surface.')],resource:'safesleep',resourceText:'Keep the AAP sleep guidance handy',foot:'Follow new abilities as they appear; the calendar doesn’t decide when a safety change matters.'};
if(t==='Health'){const age=nextVisitAge();if(!tooth&&month>=3&&month<=10)return {when:'Whenever the first tooth appears',title:'Know the first-tooth routine beforehand.',intro:'Teeth arrive on their own timeline. You can know the care routine before you need it.',items:[observation('Brushing starts with a tooth','The AAP recommends brushing twice daily with a rice-grain-sized smear of fluoride toothpaste.'),observation('Plan the dental connection','Arrange a first dental visit when the tooth appears, no later than the first birthday.')],resource:'toothcare',resourceText:'AAP first-tooth guidance',foot:'No prediction of when the tooth will arrive.'};return {when:'Ahead of the '+age+'-month visit',title:'Keep your questions ready for the conversation.',intro:'Feeding, sleep, development and prevention all belong in a routine visit.',items:[observation('Bring a specific observation','Describe what you noticed and when it changed. You can ask sooner if a concern arises.')],resource:'visits',resourceText:'See the AAP visit schedule',foot:'Your care team may tailor the schedule.'};}
if(t==='Sleep'&&month<=3)return {when:'Around the coming four-month stage',title:'Sleep patterns can change as they mature.',intro:'Knowing about the transition may make a change feel less surprising. It doesn’t predict a difficult week.',items:[observation('Know your starting point','Notice your baby’s current pattern so you can describe a change.'),observation('Know where to turn','Start with free pediatric sleep guidance; structured support is an option if you want it.')],resource:'aap',resourceText:'Get familiar with the sleep basics',foot:'Babies have different sleep needs; a calendar label does not explain every waking.'};
if(t==='Sleep')return {when:'Before you choose more support',title:'Know your options before you need to decide.',intro:'If you want more structure, you can compare approaches in your own time.',items:[observation('Start with medical and feeding questions','Discuss illness, feeding or growth concerns with your pediatrician.'),observation('Look at the approach before buying','Taking Cara Babies is one commercial option. Check the method, cost and fit.')],resource:'cara',resourceText:'Understand this optional sleep resource',foot:'A course is optional. No sleep-training deadline is implied.'};
if(t==='Daily rhythm'&&month>=3&&month<=6&&!started)return {when:'When foods join the day',title:'Make a little room for meals.',intro:'Before starting, picture where a supervised meal could fit alongside milk, play and rest.',items:[observation('Start with a place, not a strict schedule','Think about a supported meal setup and a moment when you can stay close.'),observation('Keep the transition flexible','Readiness and individual needs matter more than fitting an exact timetable.')],resource:'readiness',resourceText:'Understand the transition to foods',foot:'Preparation is useful even while milk feeds remain the current focus.'};
return {when:'As the next stage unfolds',title:'Keep familiar moments flexible.',intro:'New skills and changing needs can shift what the day looks like.',items:[observation('Follow their interest','A familiar book, song or supervised play moment can adapt with your baby.')],resource:'play',resourceText:'AAP ideas for the next stage',foot:'You don’t need to fill the day with activities.'};}
