d.groups=d.groups.map(g=>({...g,items:g.items.filter(i=>!omit.has(i.text)).map(i=>({...i,detail:copy[i.text]||i.detail}))})).filter(g=>g.items.length);
if(t==='Feeding'){d.groups.unshift(group('Milk feeds','feed',[observation('Milk',isCurrent()&&answers.solids==='Yes'?milkName()+' remains important alongside foods.':milkName()+' is the current focus.')]));d.intro='';}
if(t==='Health')d.intro='';if(t==='Safety')d.intro='';if(t==='Daily rhythm')d.intro='';
