'swipes-at-toys':['Put a suitable baby toy within arm’s reach during awake back play.',['page-pat']],
'brings-hands-to-mouth':['Let baby explore their own hands during awake play. There’s no need to guide them.',[]],
'pushes-onto-elbows-during-tummy-time':['During supervised awake tummy time, put your face or a picture at baby’s eye level.',['tummy-picture','floor-company']],
'knows-familiar-people':['Name familiar people as they arrive: “Here’s Grandma.”',['family-photos']],
'likes-looking-at-self-in-a-mirror':['Look in a shatterproof baby mirror together and smile at the reflection.',['mirror-company','mirror-faces']],
'laughs':['Repeat the gentle game that makes baby laugh. Stop when they look away or tire.',['peek-face']],
'takes-turns-making-sounds-with-you':['Copy baby’s sound, wait for their reply, then answer again.',['sound-answer','sock-puppet']],
'blows-raspberries':['Copy a raspberry baby makes and pause for their response; there’s no need to prompt one.',[]],
'squeals':['Respond to baby’s excited sounds and leave room for an answer.',[]],
'puts-things-in-mouth-to-explore':['Offer an intact, age-appropriate mouthing toy, letting baby explore while you stay close.',['texture-pair']],
'reaches-to-grab-a-toy':['Hold a favorite toy just within reach and let baby reach for it.',['roll-interest','supported-reach']],
'closes-lips-to-show-they-don-t-want-more-food':['Pause the feed when baby closes their mouth; let their cues guide whether you continue.',[]],
'rolls-tummy-to-back':['During awake floor play, place a toy slightly to one side; let baby choose their movement.',['roll-interest']],
'pushes-up-with-straight-arms-on-tummy':['Give supervised tummy time on a firm floor mat, with an interesting face or toy ahead.',['tummy-picture']],
'leans-on-hands-when-sitting':['Support baby during floor sitting, staying close while their hands help them balance.',['supported-reach']],
'may-be-shy-or-clingy-with-strangers':['Stay close as baby meets someone, letting them watch before moving into an interaction.',[]],
'shows-different-facial-expressions':['Name the feeling you notice: “You look surprised!”',['mirror-faces']],
'looks-when-you-call-their-name':['Use baby’s name in everyday talk, then pause. There’s no need to test it over and over.',[]],
'reacts-when-you-leave':['Use a short goodbye instead of slipping away, and greet baby when you return.',[]],
'enjoys-peekaboo':['Hide your face behind your hands, pop back, then wait for baby’s reaction.',['peek-corner','peek-face']],
