if(['hold-toy','transfer','banging','mouth-toy'].includes(scene)){art+=ball(scene==='mouth-toy'?139:99,scene==='mouth-toy'?91:120,12);if(scene==='banging')art+=ball(156,120,12);if(scene==='transfer')art+='<path d="M115 124h27m-6-4 6 4-6 4" fill="none" stroke="#a0af84"/>';}
