function devSkillVisual(skill){return DEV_VISUALS[skill.key];}
const DEV_COMPARISONS=['rolls-tummy-to-back','gets-into-sitting','puts-an-object-in-a-container','looks-for-something-you-hide','pulls-up-to-stand','steps-while-holding-furniture'];
function devVisualSequence(skill){const v=devSkillVisual(skill);if(!DEV_COMPARISONS.includes(skill.key)||!v?.[1])return '';return `<div class="development-visual-sequence" aria-label="Illustrated examples"><figure>${devMilestoneArt(v[0],false,skill.age)}<figcaption>${v[1]}</figcaption></figure><figure>${devMilestoneArt(v[2],false,skill.age)}<figcaption>${v[3]}</figcaption></figure></div>`;}
function devSkillExampleLink(skill){const example=DEV_EXAMPLE_LINKS[skill.key];return example?`<a class="development-action-example" href="${example.href}" target="_blank" rel="noopener"><span class="development-example-play" aria-hidden="true">${example.type==='video'?'▷':icon('dev')}</span><span><b>${example.type==='video'?'Watch a CDC example':'See a CDC example'}</b><small>${example.type==='video'?'Video · opens YouTube':'Photo'} ↗</small></span><span aria-hidden="true">›</span></a>`:'';}
function devExamplePoints(text){return text.split(/(?<=[.!?])\s+|(?<=[.!?][”"'])\s+/).filter(Boolean);}
function devSkillPagination(skill){const skills=journeySkills().filter(s=>s.age===skill.age),index=skills.findIndex(s=>s.key===skill.key),previous=skills[index-1],next=skills[index+1];return `<nav class="play-activity-pagination development-card-navigation" aria-label="More skills">${previous?`<button class="textlink" onclick="moveDevelopmentSkill('${skill.key}',-1)">← Previous skill</button>`:'<span></span>'}${next?`<button class="textlink" onclick="moveDevelopmentSkill('${skill.key}',1)">Next: ${clearMilestone(next.label)} →</button>`:''}</nav>`;}
function moveDevelopmentSkill(key,direction){const skills=journeySkills(),skill=skills.find(s=>s.key===key);if(!skill||![1,-1].includes(direction))return;const group=skills.filter(s=>s.age===skill.age),next=group[group.findIndex(s=>s.key===key)+direction];if(!next)return;rememberScroll();page='skill-guide:'+next.key;render();window.scrollTo(0,0);}
function devQuickNavigation(skill){const group=journeySkills().filter(s=>s.age===skill.age),index=group.findIndex(s=>s.key===skill.key);return `<nav class="development-quick-navigation" aria-label="Move between skill cards">${index>0?`<button onclick="moveDevelopmentSkill('${skill.key}',-1)" aria-label="Previous skill">${icon('back')}</button>`:''}${index<group.length-1?`<button onclick="moveDevelopmentSkill('${skill.key}',1)" aria-label="Next skill">Next ${icon('arrow')}</button>`:''}</nav>`;}
function devSkillFooter(skill){return `<section class="guide-footer development-footer"><details class="sources-disclosure"><summary>Source and when to ask <span aria-hidden="true">＋</span></summary><p>Adapted from CDC’s Learn the Signs. Act Early. These guides do not replace developmental screening.</p><p>If baby isn’t showing this skill by ${skill.age===12?'1 year':skill.age+' months'}, loses it or something concerns you, ask your pediatrician. You don’t need to wait for a checkup.${profile.early&&profile.due?' Development uses adjusted age.':''}</p><a href="${devSource(skill.age)}" target="_blank" rel="noopener">CDC · ${skill.age===12?'1 year':skill.age+' months'} ↗</a></details></section><p class="exp-footer">Prototype illustrations</p>`;}
function developmentSkillGuide(key){const skill=journeySkills().find(s=>s.key===key);if(!skill)return developmentJourneyOverview();const record=journeyData().records.find(r=>r.type==='milestone'&&r.skillKey===key),meta=DEV_DOMAINS[skill.domain],support=DEV_SUPPORT[key],activity=devSkillActivity(skill),visual=devSkillVisual(skill),comparison=devVisualSequence(skill),later=skill.age>devRef(developmentMonth(actualMonth())),feeding=['opens-for-breast-or-bottle-when-hungry','closes-lips-to-show-they-don-t-want-more-food','rakes-food-with-fingers','drinks-from-an-open-cup-you-hold','picks-up-small-things-with-thumb-and-finger'].includes(key);return `<div class="quiet-category parent-guide development-journey development-skill-guide development-reference-detail development-specific development-uniform domain-${skill.domain.toLowerCase()}" style="${yearTheme('Development')}">${detailPageTop('Development',devStageRail(skill.age))}${detailHeading({context:meta.title+' · By '+(skill.age===12?'1 year':skill.age+' months')+(later?' · Looking ahead':''),title:clearMilestone(skill.label)})}<div class="development-milestone-picture">${comparison||devMilestoneArt(visual[0],false,skill.age)}</div>${timelineCompletionRow({record,route:'skill-record:'+key,prompt:'Noticed this skill?',label:'Milestone completion'})}<section class="development-skill-example" data-skill-section="notice"><h2>What it looks like</h2><p>${DEV_EXAMPLES[skill.label]}</p></section><section class="development-support" data-skill-section="support" data-skill-support="${key}"><h2>Try this</h2><p>${support[0]}</p>${!later&&activity?`<button class="textlink" onclick="openDevelopmentActivity('${key}')">Try in Play: ${activity.title} →</button>`:''}${feeding&&!later?'<button class="textlink" onclick="openPage(\'topic:Feeding\')">Your feeding guide →</button>':''}${!later&&['rolls-tummy-to-back','pulls-up-to-stand','steps-while-holding-furniture'].includes(key)?`<button class="textlink development-safety-link" onclick="openPage('topic:Safety')">Safety: what this movement changes →</button>`:''}</section>${record?.notes?`<details class="guide-detail"><summary>Your saved note <span>＋</span></summary><p>${esc(record.notes)}</p></details>`:''}${devSkillPagination(skill)}${devSkillExampleLink(skill)}${devSkillFooter(skill)}</div>`;}
function developmentSkillDatePage(key){const skill=journeySkills().find(s=>s.key===key);if(!skill)return developmentJourneyOverview();return `<div class="visit-completion-page development-date-page" style="${yearTheme('Development')}">${backButton()}<header class="visit-completion-intro"><div class="eyebrow">A moment you noticed</div><span class="visit-completion-art" aria-hidden="true">${yearIllustration('Development',skill.domain==='Movement'?4:1)}</span><h1>${clearMilestone(skill.label)}</h1><p>When did you notice it?</p></header><form class="form journey-form visit-date-panel" onsubmit="submitJourneySkill(event,'${key}')"><label for="skillDate">Date noticed</label><input id="skillDate" type="date" min="${profile.dob}" max="${iso(NOW)}" value="${iso(NOW)}" required>${journeyError?`<p class="journey-error" role="alert">${esc(journeyError)}</p>`:''}<button class="primary">Mark as complete</button><button type="button" class="textlink visit-cancel" onclick="back()">Cancel</button></form></div>`;}

